"use workflow";

import { createHash } from "node:crypto";
import { serviceClient } from "@/lib/service-db";
import { inspectRows, mappingSchema, parseCsv, parseExcel, parseLegacyExcel } from "@/lib/import/csv";
import { stableId } from "@/lib/import/row";
import { linkOwnTransfers } from "@/lib/finance/own-transfers";
import { batchDecisions, candidateRowsSchema, stageImportRows } from "@/lib/import/batch";
import { startAgentRun } from "@/lib/ai/agent-dispatch";
import { maybeStartFirstReview as startFirstReviewIfFirst } from "@/lib/import/follow-up";

function checked<T>(result: { data: T | null; error: { message: string } | null }): T | null {
  if (result.error) throw new Error(result.error.message);
  return result.data;
}

// followUps is false for a bank sync, which starts the agent team and first review once for all its accounts.
export async function importFile(importId: string, workspaceId: string, rowCount: number, runVersion = 1, followUps = true) {
  "use workflow";
  try {
    const stagedRows = rowCount === 0 ? 0 : await prepareImport(importId, workspaceId, rowCount, runVersion);
    for (let offset = 0; offset < stagedRows; offset += 250) {
      await processImportBatch(importId, workspaceId, offset, runVersion);
    }
    if (!await finishImport(importId, workspaceId, runVersion)) return;
  } catch (error) {
    await failImport(importId, workspaceId, String(error), runVersion);
    return;
  }
  await linkOwnTransfersStep(workspaceId);
  if (!followUps) return;
  await startAgentTeam(importId, workspaceId);
  await maybeStartFirstReview(importId, workspaceId);
}

// Transfers between the owner's own accounts are linked as soon as new rows land, so a later
// import from the other bank completes the pair. A failure never affects the completed import.
async function linkOwnTransfersStep(workspaceId: string) {
  "use step";
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL) return;
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
  try { await linkOwnTransfers(db, workspaceId); } catch (error) { console.error("Own-account transfers were not linked", error); } // The next import retries.
}

// The agent team starts the moment an import's rows are in. It only proposes;
// a failure here never affects the completed import.
async function startAgentTeam(importId: string, workspaceId: string) {
  "use step";
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL) return;
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
  try {
    const imported = checked(await db.from("imports").select("new_rows").eq("id", importId).eq("workspace_id", workspaceId).single()) as { new_rows: number | null };
    if (imported.new_rows) await startAgentRun(db, workspaceId, { importId });
  } catch (error) { console.error("Agent team did not start", error); } // Owners can start it from /ai/agents.
}

async function prepareImport(importId: string, workspaceId: string, rowCount: number, runVersion: number) {
  "use step";
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new Error("Supabase import service is not configured");
  const db = serviceClient(url, key);
  const imported = checked(await db.from("imports").select("*").eq("id", importId).eq("workspace_id", workspaceId).single()) as { status: string; run_version: number; source_id?: string | null; route_accounts?: Record<string, string>; storage_path: string; file_hash: string; mapping: unknown };
  if (imported.status === "completed") return 0;
  if (!["queued", "running"].includes(imported.status) || imported.run_version !== runVersion) throw new Error("Import worker canceled or superseded");
  const stagedCount = checked(await db.rpc("read_import_stage", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion }));
  if (stagedCount !== null) {
    if (stagedCount !== rowCount) throw new Error("Normalized import coverage differs from reviewed rows");
    return rowCount;
  }
  if (!imported.storage_path.startsWith(`${workspaceId}/`)) throw new Error("Import file is outside the workspace");
  const blob = checked(await db.storage.from("imports").download(imported.storage_path));
    if (!blob) throw new Error("Stored import file is missing");
    if (blob.size > 10_000_000) throw new Error("Stored import file exceeds the 10 MB limit");
    const bytes = await blob.arrayBuffer();
    if (createHash("sha256").update(new Uint8Array(bytes)).digest("hex") !== imported.file_hash) throw new Error("Stored import file differs from the reviewed original");
    const extension = imported.storage_path.split(".").pop();
    const confirmedMapping = mappingSchema.parse(imported.mapping);
    const rows = extension === "csv" ? parseCsv(new TextDecoder().decode(bytes)) : confirmedMapping.workbookScope ? await parseExcel(bytes, confirmedMapping.workbookScope) : await parseLegacyExcel(bytes);
    const { mapped, unresolvedRows, excludedRows } = inspectRows(rows, imported.mapping);
    if (unresolvedRows.length) throw new Error(unresolvedRows[0].message);
    const accountIds = new Map<string, string>();
    let preparedSourceId = imported.source_id ?? null;
    const frozenAccounts = new Map(Object.entries(imported.route_accounts ?? {}).map(([route, accountId]) => [JSON.stringify(JSON.parse(route)), accountId]));
    const legacyPrepared = frozenAccounts.size === 0 && !!imported.source_id;
    if (legacyPrepared) {
      const firstSource = checked(await db.from("data_sources").select("account_id").eq("workspace_id", workspaceId).eq("id", imported.source_id!).eq("kind", "file").single()) as { account_id: string | null };
      if (!firstSource.account_id || !mapped[0]) throw new Error("Legacy import route evidence is unavailable");
      frozenAccounts.set(JSON.stringify([mapped[0].accountName, mapped[0].currencyCode]), firstSource.account_id);
      const byNumber = new Map(mapped.map(row => [row.rowNumber, row]));
      type LegacySource = { row_number: number; transaction_sources: { transactions: { account_id: string } | null }[] | { transactions: { account_id: string } | null } | null };
      for (let offset = 0; ; offset += 500) {
        const sources = checked(await db.from("source_transactions").select("row_number, transaction_sources(transactions(account_id))").eq("workspace_id", workspaceId).eq("import_id", importId).order("id").range(offset, offset + 499)) as unknown as LegacySource[];
        for (const source of sources) {
          const mappedRow = byNumber.get(source.row_number);
          const links = Array.isArray(source.transaction_sources) ? source.transaction_sources : [source.transaction_sources];
          for (const link of links) if (link?.transactions?.account_id) {
            if (!mappedRow) throw new Error("Legacy source row differs from the reviewed file");
            const route = JSON.stringify([mappedRow.accountName, mappedRow.currencyCode]);
            if (frozenAccounts.has(route) && frozenAccounts.get(route) !== link.transactions.account_id) throw new Error("Legacy import route has conflicting account evidence");
            frozenAccounts.set(route, link.transactions.account_id);
          }
        }
        if (sources.length < 500) break;
      }
    }
    for (const row of mapped) {
      const routeKey = JSON.stringify([row.accountName, row.currencyCode]);
      if (accountIds.has(routeKey)) continue;
      const frozenAccountId = frozenAccounts.get(routeKey);
      if (legacyPrepared && !frozenAccountId) throw new Error("Legacy partial import route needs review before resume");
      let accountQuery = db.from("accounts").select("id, archived_at").eq("workspace_id", workspaceId).eq("currency_code", row.currencyCode);
      accountQuery = frozenAccountId ? accountQuery.eq("id", frozenAccountId) : accountQuery.eq("name", row.accountName);
      const existingAccount = checked(await accountQuery.limit(2))!;
      if (existingAccount.length > 1) throw new Error("Reviewed import account is ambiguous");
      if (frozenAccountId && !existingAccount.length) throw new Error("Frozen import account unavailable; review the destination before resume");
      if (existingAccount[0]?.archived_at) throw new Error("Archived accounts cannot receive new imports");
      const accountId = frozenAccountId ?? existingAccount[0]?.id ?? stableId(`${workspaceId}:account:${row.accountName}:${row.currencyCode}`);
      accountIds.set(routeKey, accountId);
      const sourceId = stableId(`${workspaceId}:source:${accountId}`);
      preparedSourceId ??= sourceId;
      checked(await db.rpc("prepare_import_route", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion,
        p_account_id: accountId, p_source_id: sourceId, p_account_name: row.accountName, p_currency_code: row.currencyCode, p_total_rows: rows.length }));
    }

    const stagedRows = stageImportRows(workspaceId, importId, mapped, excludedRows, accountIds, rowCount);
    checked(await db.rpc("stage_import_rows", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_file_hash: imported.file_hash,
      p_mapping: imported.mapping, p_routes: imported.route_accounts ?? {}, p_source_id: preparedSourceId, p_rows: stagedRows }));
    return rowCount;
}

async function processImportBatch(importId: string, workspaceId: string, offset: number, runVersion: number) {
  "use step";
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  // Retry stale candidate evidence inside the same durable step. Every attempt
  // rereads candidates and every batch transaction fences canceled/old workers.
  for (let attempt = 0; attempt < 3; attempt++) {
    const candidates = checked(await db.rpc("import_batch_candidates", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_offset: offset }));
    const decisions = batchDecisions(candidateRowsSchema.parse(candidates));
    const result = await db.rpc("ingest_import_batch", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_offset: offset, p_decisions: decisions });
    if (!result.error) return;
    if (result.error.code !== "PT409" || attempt === 2) throw new Error(result.error.message);
  }
}

async function finishImport(importId: string, workspaceId: string, runVersion: number) {
  "use step";
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  return checked(await db.rpc("finish_import_run", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_error: null })) === "completed";
}

async function failImport(importId: string, workspaceId: string, error: string, runVersion: number) {
  "use step";
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  checked(await db.rpc("finish_import_run", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_error: error }));
}

// Keeps its step name so imports already running when Moneo updates resume cleanly.
async function maybeStartFirstReview(importId: string, workspaceId: string) {
  "use step";
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL) return;
  await startFirstReviewIfFirst(serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY), workspaceId, [importId]);
}
import {z} from 'zod';

const rowSchema = z.object({id: z.uuid(), version: z.number().int().min(0).max(2147483647), description: z.string().min(1).max(1000),
  merchantId: z.uuid().nullable(), categoryId: z.uuid().nullable(), kind: z.enum(['ordinary', 'refund', 'transfer']),
  reviewReasons: z.array(z.string().max(200)).max(20), userCorrected: z.boolean()}).strict();
/** Every saved Apply teaches a rule, so a workspace collects many; suggestions read all of them up to this bound. */
export const MAX_ORGANIZATION_RULES = 2000;
export const organizationRuleSchema = z.object({id: z.uuid(), version: z.number().int().min(1), descriptionKey: z.string().min(3).max(1000),
  merchantId: z.uuid().nullable(), categoryId: z.uuid().nullable(), approvedBy: z.uuid(), enabled: z.boolean()}).strict();
export type OrganizationRow = z.infer<typeof rowSchema>;
export type OrganizationRule = z.infer<typeof organizationRuleSchema>;
export type OrganizationProposal = {transactionId: string; version: number; descriptionKey: string; merchantId: string | null; categoryId: string | null;
  merchantName: string | null; basis: 'approved-rule' | 'consistent-history' | 'review-required' | 'provider-suggestion'; financialReviewRequired: boolean; evidence: {id: string; version: number}[];
  rule?: {id: string; version: number}; evidenceQuote?: string};
export const organizationSuggestionsSchema = z.array(z.object({transactionId: z.uuid(), merchantName: z.string().trim().min(1).max(100).nullable(),
  categoryId: z.uuid().nullable(), evidenceQuote: z.string().min(1).max(100)}).strict()).max(50)
  .refine(values => new Set(values.map(value => value.transactionId)).size === values.length);

export function mergeOrganizationSuggestions(rows: OrganizationRow[], proposals: OrganizationProposal[], input: unknown, categoryIds: string[]): OrganizationProposal[] {
  const suggestions = organizationSuggestionsSchema.parse(input);
  const byId = new Map(rows.map(row => [row.id, row]));
  const ownedCategories = new Set(categoryIds);
  for (const suggestion of suggestions) {
    const row = byId.get(suggestion.transactionId);
    if (!row || row.userCorrected || !proposals.some(proposal => proposal.transactionId === row.id) ||
      !row.description.includes(suggestion.evidenceQuote) || (suggestion.categoryId && !ownedCategories.has(suggestion.categoryId)))
      throw new Error('Suggestion requires the selected unchanged source and an owned category');
  }
  const bySuggestion = new Map(suggestions.map(suggestion => [suggestion.transactionId, suggestion]));
  return proposals.map(proposal => {
    const suggestion = bySuggestion.get(proposal.transactionId);
    if (!suggestion || proposal.basis !== 'review-required') return proposal;
    return {...proposal, categoryId: proposal.categoryId ?? suggestion.categoryId,
      merchantName: proposal.merchantId ? null : suggestion.merchantName ?? proposal.merchantName,
      basis: 'provider-suggestion', evidenceQuote: suggestion.evidenceQuote};
  });
}

/**
 * What a payment is "from" for matching: bank text without dates, amounts, IBANs, reference numbers or the trailing SEPA
 * fields, each word once. Monthly payments whose bank text differs only in those details share one key, so one rule covers them.
 */
export function organizationDescriptionKey(description: string) {
  const words = description.normalize('NFKC')
    .replace(/\b[A-Z]{6}[A-Z0-9]{2}(?:[A-Z0-9]{3})?\s+[A-Z]{2}\d{2}[A-Z0-9]{10,30}\b/gu, ' ')
    .toLocaleLowerCase('en')
    .replace(/(?:end-to-end-ref|kundenreferenz|mandatsref|gläubiger-id|sepa-basislastschrift|\d{4}-\d{2}-\d{2}t\d).*$/su, ' ')
    .replace(/\b(?:ref(?:erence)?|invoice|order|receipt|terminal)\b\s*[:#-]?\s*[a-z0-9-]*\d[a-z0-9-]*\b/gu, ' ')
    .replace(/^\s*(?:(?:card payment|pos purchase|card purchase)\s+)+/u, '')
    .split(/[^\p{L}\p{N}]+/u).filter(Boolean);
  // Words with digits are dates and references, and single letters are leftovers like "D" or "K"; a name made only of them ("O2", "H&M") keeps them.
  const named = words.filter(word => word.length > 1 && !/\d/u.test(word));
  return [...new Set(named.length ? named : words.filter(word => /\p{L}/u.test(word)))].join(' ');
}

/** A person-facing name for a matching key: the first few words, capitalized, instead of the bank's raw text. */
export function organizationDisplayName(key: string) {
  const words = key.split(' ').filter(Boolean);
  const name = words.slice(0, 5).map(word => word[0].toLocaleUpperCase('de') + word.slice(1)).join(' ');
  return words.length > 5 ? name + '…' : name;
}

export function organizationProposals(rows: OrganizationRow[], history: OrganizationRow[], rules: OrganizationRule[]): OrganizationProposal[] {
  z.array(rowSchema).max(50).refine(values => new Set(values.map(row => row.id)).size === values.length).parse(rows);
  z.array(rowSchema).max(2000).refine(values => new Set(values.map(row => row.id)).size === values.length).parse(history);
  z.array(organizationRuleSchema).max(MAX_ORGANIZATION_RULES).refine(values => new Set(values.filter(rule => rule.enabled).map(rule => rule.descriptionKey)).size === values.filter(rule => rule.enabled).length).parse(rules);
  const approved = new Map(rules.filter(rule => rule.enabled).map(rule => [rule.descriptionKey, rule]));
  const grouped = new Map<string, OrganizationRow[]>();
  for (const row of history) {
    const key = organizationDescriptionKey(row.description);
    if (key.length < 3 || row.kind !== 'ordinary' || row.reviewReasons.length) continue;
    const entries = grouped.get(key) ?? []; entries.push(row); grouped.set(key, entries);
  }
  const proposals: OrganizationProposal[] = [];
  for (const row of rows) {
    if (row.userCorrected || (row.merchantId && row.categoryId)) continue;
    const descriptionKey = organizationDescriptionKey(row.description), rule = approved.get(descriptionKey);
    const evidence = (grouped.get(descriptionKey) ?? []).filter(value => value.id !== row.id).sort((a, b) => a.id.localeCompare(b.id));
    const merchants = new Set(evidence.map(value => value.merchantId));
    const categories = new Set(evidence.map(value => value.categoryId));
    const merchantId = evidence.length >= 3 && merchants.size === 1 ? evidence[0].merchantId : null;
    const categoryId = evidence.length >= 3 && categories.size === 1 ? evidence[0].categoryId : null;
    proposals.push({transactionId: row.id, version: row.version, descriptionKey,
      merchantId: row.merchantId ?? rule?.merchantId ?? merchantId, categoryId: row.categoryId ?? rule?.categoryId ?? categoryId,
      merchantName: row.merchantId || rule?.merchantId || merchantId || descriptionKey.length < 3 || row.reviewReasons.length || row.kind === 'transfer' ? null : Array.from(descriptionKey).slice(0, 100).join(''),
      basis: rule ? 'approved-rule' : merchantId && categoryId ? 'consistent-history' : 'review-required',
      financialReviewRequired: row.reviewReasons.length > 0 || row.kind === 'transfer',
      evidence: evidence.map(value => ({id: value.id, version: value.version})), ...(rule ? {rule: {id: rule.id, version: rule.version}} : {})});
  }
  return proposals.sort((a, b) => Number(b.financialReviewRequired) - Number(a.financialReviewRequired) || a.transactionId.localeCompare(b.transactionId));
}
-- The bank's full transaction beside the 8-column statement CSV (which must never change: its bytes are the dedupe hash).
-- One row per CSV row, keyed like source_transactions (import_id, row_number). The normalized columns are generic
-- (any bank on Enable Banking) context for the organizer; they never feed ledger amounts. Written by the bank sync
-- (service role); the owner can read it. Removed with its import on undo, and on reset.
create table public.bank_transaction_raw (
  import_id uuid not null references public.imports(id) on delete cascade,
  row_number integer not null check (row_number >= 2),
  workspace_id uuid not null references public.workspaces(id),
  bank_id text check (char_length(bank_id) <= 500),
  raw jsonb not null default '{}' check (jsonb_typeof(raw) = 'object' and octet_length(raw::text) <= 65536),
  payment_type text not null default 'unknown' check (payment_type in ('card','transfer','direct_debit','cash','fee_interest','top_up','exchange','unknown')),
  bank_code text check (char_length(bank_code) <= 200),
  bank_sub_code text check (char_length(bank_sub_code) <= 200),
  mcc text check (char_length(mcc) <= 10),
  counterparty_name text check (char_length(counterparty_name) <= 500),
  counterparty_iban text check (char_length(counterparty_iban) <= 34),
  counterparty_bic text check (char_length(counterparty_bic) <= 11),
  counterparty_ids jsonb not null default '[]' check (jsonb_typeof(counterparty_ids) = 'array' and octet_length(counterparty_ids::text) <= 8192),
  own_side_ids jsonb not null default '[]' check (jsonb_typeof(own_side_ids) = 'array' and octet_length(own_side_ids::text) <= 8192),
  creditor_id text check (char_length(creditor_id) <= 40),
  mandate_ref text check (char_length(mandate_ref) <= 40),
  -- Context only, as the bank states them: never used for ledger amounts.
  instructed_amount text check (char_length(instructed_amount) <= 40),
  instructed_currency text check (instructed_currency ~ '^[A-Z]{3}$'),
  exchange_rate text check (char_length(exchange_rate) <= 40),
  own_account boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (import_id, row_number)
);
create index bank_transaction_raw_workspace_idx on public.bank_transaction_raw(workspace_id);

alter table public.bank_transaction_raw enable row level security;
create policy bank_transaction_raw_owned on public.bank_transaction_raw for select using (public.owns_workspace(workspace_id));
revoke all on public.bank_transaction_raw from anon, authenticated;
grant select on public.bank_transaction_raw to authenticated;
grant all on public.bank_transaction_raw to service_role;

-- Undoing an import removes the rows it brought, and so the bank data kept for them. (The import row stays as history;
-- a later sync of the same window makes a new import and writes its own rows.)
create function public.remove_undone_bank_raw() returns trigger language plpgsql security definer set search_path='' as $$
begin
  delete from public.bank_transaction_raw where import_id = new.id;
  return new;
end;
$$;
revoke all on function public.remove_undone_bank_raw() from public, anon, authenticated;
create trigger imports_remove_bank_raw after update of status on public.imports
  for each row when (new.status = 'undone' and old.status is distinct from 'undone') execute function public.remove_undone_bank_raw();

create or replace function public.reset_workspace() returns void language plpgsql security definer set search_path='' as $$
declare ws uuid; owner uuid := auth.uid();
begin
  if owner is null then raise exception 'Unauthorized' using errcode='42501'; end if;
  select id into ws from public.workspaces where owner_id=owner for update;
  if not found then raise exception 'Workspace unavailable' using errcode='P0002'; end if;
  -- Deleted history is not undoable, so skip planning audit rows and link-edit guards.
  perform set_config('moneo.planning_undo','true',true);
  perform set_config('moneo.link_edit','on',true);

  -- Agent team runs, tasks and proposals.
  delete from public.agent_proposals where workspace_id=ws;
  delete from public.agent_tasks where workspace_id=ws;
  delete from public.agent_runs where workspace_id=ws;

  -- AI conversations and reviews.
  delete from public.saved_analyses where workspace_id=ws;
  delete from public.summary_runs where workspace_id=ws;
  delete from public.background_jobs where workspace_id=ws;
  delete from public.chat_requests where workspace_id=ws;
  delete from public.messages where workspace_id=ws;
  delete from public.conversations where workspace_id=ws;
  delete from public.dashboard_layouts where workspace_id=ws;

  -- Preferences, views and settings.
  delete from public.insight_dismissals where workspace_id=ws;
  delete from public.insight_preferences where workspace_id=ws;
  delete from public.financial_evidence_receipts where workspace_id=ws;
  delete from public.transaction_views where workspace_id=ws;
  delete from public.fx_rates where workspace_id=ws;
  delete from public.workspace_settings where workspace_id=ws;

  -- Everything that points at transactions.
  delete from public.transaction_link_fees where workspace_id=ws;
  delete from public.transaction_links where workspace_id=ws;
  delete from public.transaction_splits where workspace_id=ws;
  delete from public.transaction_split_sets where workspace_id=ws;
  delete from public.pending_hold_resolutions where workspace_id=ws;
  delete from public.correction_events where workspace_id=ws;
  delete from public.recurring_occurrence_settlements where workspace_id=ws;
  delete from public.recurring_series_transactions where workspace_id=ws;
  delete from public.recurring_series where workspace_id=ws;
  delete from public.manual_transaction_entries where workspace_id=ws;
  delete from public.money_metadata_events where workspace_id=ws;
  delete from public.organization_reviews where workspace_id=ws;
  delete from public.organization_rules where workspace_id=ws;
  delete from public.transaction_batches where workspace_id=ws;
  delete from public.scalable_value_history where workspace_id=ws;
  delete from public.wealth_events where workspace_id=ws;
  delete from public.wealth_items where workspace_id=ws;
  delete from public.transaction_sources where transaction_id in (select id from public.transactions where workspace_id=ws)
    or source_transaction_id in (select id from public.source_transactions where workspace_id=ws);
  delete from public.balance_snapshots where workspace_id=ws;
  update public.transactions set transfer_id=null, refund_of_id=null
    where workspace_id=ws and (transfer_id is not null or refund_of_id is not null);
  delete from public.transactions where workspace_id=ws;

  delete from public.bank_transaction_raw where workspace_id=ws;

  -- Bank connections, then imports.
  delete from public.bank_connection_accounts where workspace_id=ws;
  delete from public.bank_connections where workspace_id=ws;

  -- Imports.
  delete from public.source_transactions where workspace_id=ws;
  delete from public.import_control_events where workspace_id=ws;
  delete from public.import_staging where workspace_id=ws;
  delete from public.imports where workspace_id=ws;
  delete from public.data_sources where workspace_id=ws;

  -- Goals, plans, scenarios and budgets.
  delete from public.goal_reservation_events where workspace_id=ws;
  delete from public.goal_allocations where workspace_id=ws;
  delete from public.goal_events where workspace_id=ws;
  delete from public.goals where workspace_id=ws;
  delete from public.forecast_runs where workspace_id=ws;
  delete from public.scenario_overrides where workspace_id=ws;
  delete from public.scenario_events where workspace_id=ws;
  delete from public.scenarios where workspace_id=ws;
  delete from public.spending_plan_limits where workspace_id=ws;
  delete from public.spending_plans where workspace_id=ws;
  delete from public.financial_assumptions where workspace_id=ws;
  delete from public.planning_events where workspace_id=ws;
  delete from public.forecast_preference_events where workspace_id=ws;
  delete from public.forecast_preferences where workspace_id=ws;

  -- Remaining parents, then a fresh workspace exactly like create_private_workspace().
  delete from public.merchants where workspace_id=ws;
  delete from public.categories where workspace_id=ws;
  delete from public.accounts where workspace_id=ws;
  delete from public.workspaces where id=ws;
  insert into public.workspaces(owner_id) values(owner);
end;
$$;

-- AI organization labels get their own provenance. The organizer writes category and merchant labels
-- itself (the one AI write without a card), marked as AI and logged in organizer_ops for Undo. They
-- never become owner corrections or organization rules, so they never count as evidence either.

-- Who set a row's labels: null = not organized yet (or before this migration).
alter table public.transactions add column organized_by text check (organized_by in ('owner','rule','memory','ai','system'));
alter table public.transactions add column ai_confidence text check (ai_confidence in ('high','medium','low'));
alter table public.transactions add column ai_reason text check (char_length(ai_reason) <= 500);
alter table public.transactions add column organize_op_id uuid;

-- Events the old auto-apply left behind are stamped 'ai' so they never count as owner corrections.
alter table public.correction_events add column origin text not null default 'owner' check (origin in ('owner','ai'));

-- Later the AI may change only categories and merchants it made and the owner never used.
alter table public.categories add column created_by text not null default 'owner' check (created_by in ('owner','ai'));
alter table public.categories add column owner_touched boolean not null default false;
alter table public.merchants add column created_by text not null default 'owner' check (created_by in ('owner','ai'));
alter table public.merchants add column owner_touched boolean not null default false;

-- One row per AI label write: the Undo record and, once undone, a "don't suggest this again" marker
-- for (identity_key, category or merchant). identity_key is today's organization description key.
create table public.organizer_ops (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  run_id uuid references public.agent_runs(id) on delete set null,
  proposal_id uuid references public.agent_proposals(id) on delete set null,
  transaction_id uuid not null references public.transactions(id) on delete cascade,
  identity_key text not null check (char_length(identity_key) <= 1000),
  category_id uuid,
  merchant_id uuid,
  before jsonb not null,
  after jsonb not null,
  created_at timestamptz not null default now(),
  undone_at timestamptz,
  suppressed boolean not null default false,
  check (category_id is not null or merchant_id is not null)
);
create index organizer_ops_workspace_created on public.organizer_ops(workspace_id, created_at desc);
create index organizer_ops_transaction on public.organizer_ops(transaction_id);
create index organizer_ops_proposal on public.organizer_ops(proposal_id) where proposal_id is not null;
create index organizer_ops_suppressed on public.organizer_ops(workspace_id, identity_key) where suppressed;
alter table public.organizer_ops enable row level security;
create policy organizer_ops_owned on public.organizer_ops for select using (public.owns_workspace(workspace_id));
revoke all on public.organizer_ops from anon, authenticated;
grant select on public.organizer_ops to authenticated, service_role;

-- An owner correction that changes a row's category or merchant makes the owner its organizer. The
-- event keeps the previous provenance in `before`, so undoing the edit restores an AI row exactly.
-- Every owner path (quick edit, chat, bulk edit, organization review) writes such an event.
create function public.stamp_owner_organization() returns trigger language plpgsql security definer set search_path='' as $$
declare current_row public.transactions%rowtype; category_changed boolean; merchant_changed boolean;
begin
  if new.origin<>'owner' then return new; end if;
  category_changed := new.before ? 'category_id' and new.after ? 'category_id' and new.before->'category_id' is distinct from new.after->'category_id';
  merchant_changed := new.before ? 'merchant_id' and new.after ? 'merchant_id' and new.before->'merchant_id' is distinct from new.after->'merchant_id';
  if not (category_changed or merchant_changed) then return new; end if;
  select * into current_row from public.transactions where id=new.transaction_id and workspace_id=new.workspace_id;
  if not found then return new; end if;
  new.before := new.before || jsonb_build_object('organized_by',current_row.organized_by,'ai_confidence',current_row.ai_confidence,
    'ai_reason',current_row.ai_reason,'organize_op_id',current_row.organize_op_id);
  new.after := new.after || jsonb_build_object('organized_by','owner','ai_confidence',null,'ai_reason',null,'organize_op_id',null);
  update public.transactions set organized_by='owner',ai_confidence=null,ai_reason=null,organize_op_id=null where id=current_row.id;
  if category_changed and new.after->>'category_id' is not null then
    update public.categories set owner_touched=true where id=(new.after->>'category_id')::uuid and workspace_id=new.workspace_id and not owner_touched;
  end if;
  if merchant_changed and new.after->>'merchant_id' is not null then
    update public.merchants set owner_touched=true where id=(new.after->>'merchant_id')::uuid and workspace_id=new.workspace_id and not owner_touched;
  end if;
  return new;
end;
$$;
create trigger correction_events_owner_organization before insert on public.correction_events for each row execute function public.stamp_owner_organization();

-- Undoing any correction that recorded provenance puts that provenance back with the labels.
create function public.restore_undone_organization() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if new.undone and not old.undone and new.before ? 'organized_by' then
    update public.transactions set organized_by=new.before->>'organized_by',ai_confidence=new.before->>'ai_confidence',
      ai_reason=new.before->>'ai_reason',organize_op_id=(new.before->>'organize_op_id')::uuid
      where id=new.transaction_id and workspace_id=new.workspace_id;
  end if;
  return null;
end;
$$;
create trigger correction_events_restore_organization after update of undone on public.correction_events for each row execute function public.restore_undone_organization();

-- Splitting a row into a category is the owner using that category.
create function public.touch_split_category() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if new.category_id is not null then
    update public.categories set owner_touched=true where id=new.category_id and workspace_id=new.workspace_id and not owner_touched;
  end if;
  return null;
end;
$$;
create trigger transaction_splits_owner_touch after insert on public.transaction_splits for each row execute function public.touch_split_category();
revoke all on function public.stamp_owner_organization(),public.restore_undone_organization(),public.touch_split_category() from public,anon,authenticated;

-- The organizer's write path (service role only). Fills only empty labels, never on rows the owner
-- organized or corrected, split rows, rows changed since the suggestion, or suggestions the owner
-- undid for the same identity. No correction events, no rules, no auth claims.
create function public.apply_ai_organization(p_workspace uuid,p_run uuid,p_items jsonb,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  item jsonb; t public.transactions%rowtype; ids uuid[]; new_category uuid; new_merchant uuid; merchant_name text; normalized text;
  create_merchant boolean; was_suppressed boolean; op uuid; reason text; applied uuid[]:='{}'; skipped jsonb:='{}';
begin
  if p_workspace is null or not exists(select 1 from public.workspaces where id=p_workspace) then raise exception 'Workspace not found' using errcode='P0002'; end if;
  if p_run is not null and not exists(select 1 from public.agent_runs where id=p_run and workspace_id=p_workspace) then raise exception 'Run not found' using errcode='P0002'; end if;
  if p_proposal is not null and not exists(select 1 from public.agent_proposals where id=p_proposal and workspace_id=p_workspace) then raise exception 'Proposal not found' using errcode='P0002'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 500 then raise exception 'Invalid AI organization' using errcode='22023'; end if;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item)<>'object' or item-array['transaction_id','expected_version','category_id','merchant_id','merchant_name','confidence','reason','identity_key']<>'{}'::jsonb
      or jsonb_typeof(item->'transaction_id') is distinct from 'string' or coalesce(item->>'expected_version','') !~ '^[0-9]+$'
      or coalesce(item->>'confidence','') not in ('high','medium','low')
      or jsonb_typeof(item->'identity_key') is distinct from 'string' or char_length(item->>'identity_key')>1000
      or coalesce(jsonb_typeof(item->'reason'),'null') not in ('string','null')
      or coalesce(jsonb_typeof(item->'category_id'),'null') not in ('string','null') or coalesce(jsonb_typeof(item->'merchant_id'),'null') not in ('string','null')
      or coalesce(jsonb_typeof(item->'merchant_name'),'null') not in ('string','null')
      or (item->>'merchant_name' is not null and (char_length(btrim(item->>'merchant_name')) not between 1 and 100 or item->>'merchant_id' is not null))
      or coalesce(item->>'category_id',item->>'merchant_id',item->>'merchant_name') is null
      then raise exception 'Invalid AI organization item' using errcode='22023'; end if;
  end loop;
  select array_agg((value->>'transaction_id')::uuid) into ids from jsonb_array_elements(p_items);
  if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) then raise exception 'Duplicate AI organization row' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_items) i where (i->>'category_id' is not null and not exists(select 1 from public.categories c where c.id=(i->>'category_id')::uuid and c.workspace_id=p_workspace))
    or (i->>'merchant_id' is not null and not exists(select 1 from public.merchants m where m.id=(i->>'merchant_id')::uuid and m.workspace_id=p_workspace)))
    then raise exception 'Organization target not found' using errcode='P0002'; end if;
  -- Same lock order as the owner's bulk edits.
  perform 1 from public.transactions where id=any(ids) and workspace_id=p_workspace order by id for update;
  for item in select value from jsonb_array_elements(p_items) order by value->>'transaction_id' loop
    select * into t from public.transactions where id=(item->>'transaction_id')::uuid and workspace_id=p_workspace;
    reason := null;
    if not found then reason := 'missing';
    elsif item->>'confidence'='low' then reason := 'low_confidence';
    elsif t.version<>(item->>'expected_version')::integer then reason := 'changed';
    elsif t.organized_by='owner' then reason := 'owner';
    elsif exists(select 1 from public.correction_events e where e.transaction_id=t.id and e.workspace_id=p_workspace and not e.undone and e.origin='owner'
      and ((e.before ? 'category_id' and e.after ? 'category_id' and e.before->'category_id' is distinct from e.after->'category_id')
        or (e.before ? 'merchant_id' and e.after ? 'merchant_id' and e.before->'merchant_id' is distinct from e.after->'merchant_id'))) then reason := 'owner_corrected';
    elsif exists(select 1 from public.transaction_split_sets s where s.transaction_id=t.id and s.undone_at is null) then reason := 'split';
    end if;
    if reason is null then
      new_category := case when t.category_id is null then (item->>'category_id')::uuid end;
      new_merchant := null; create_merchant := false; was_suppressed := false; merchant_name := null;
      if t.merchant_id is null and item->>'merchant_id' is not null then new_merchant := (item->>'merchant_id')::uuid;
      elsif t.merchant_id is null and item->>'merchant_name' is not null then
        merchant_name := btrim(item->>'merchant_name'); normalized := lower(regexp_replace(merchant_name,'\s+',' ','g'));
        select id into new_merchant from public.merchants where workspace_id=p_workspace and normalized_name=normalized;
        create_merchant := new_merchant is null;
      end if;
      if new_category is not null and exists(select 1 from public.organizer_ops o where o.workspace_id=p_workspace and o.suppressed
        and o.identity_key=item->>'identity_key' and o.category_id=new_category) then new_category := null; was_suppressed := true; end if;
      if new_merchant is not null and exists(select 1 from public.organizer_ops o where o.workspace_id=p_workspace and o.suppressed
        and o.identity_key=item->>'identity_key' and o.merchant_id=new_merchant) then new_merchant := null; was_suppressed := true; end if;
      if new_category is null and new_merchant is null and not create_merchant then reason := case when was_suppressed then 'suppressed' else 'labelled' end; end if;
    end if;
    if reason is not null then
      skipped := jsonb_set(skipped,array[reason],to_jsonb(coalesce((skipped->>reason)::integer,0)+1));
      continue;
    end if;
    if create_merchant then
      insert into public.merchants(workspace_id,name,normalized_name,created_by) values(p_workspace,merchant_name,normalized,'ai') on conflict(workspace_id,normalized_name) do nothing;
      select id into strict new_merchant from public.merchants where workspace_id=p_workspace and normalized_name=normalized;
    end if;
    insert into public.organizer_ops(workspace_id,run_id,proposal_id,transaction_id,identity_key,category_id,merchant_id,before,after)
      values(p_workspace,p_run,p_proposal,t.id,item->>'identity_key',new_category,new_merchant,
        jsonb_build_object('category_id',t.category_id,'merchant_id',t.merchant_id,'organized_by',t.organized_by,'ai_confidence',t.ai_confidence,
          'ai_reason',t.ai_reason,'organize_op_id',t.organize_op_id,'version',t.version),'{}') returning id into op;
    update public.transactions set category_id=coalesce(new_category,category_id),merchant_id=coalesce(new_merchant,merchant_id),
      organized_by='ai',ai_confidence=item->>'confidence',ai_reason=left(nullif(btrim(item->>'reason'),''),500),organize_op_id=op,version=version+1
      where id=t.id returning * into t;
    update public.organizer_ops set after=jsonb_build_object('category_id',t.category_id,'merchant_id',t.merchant_id,'organized_by',t.organized_by,
      'ai_confidence',t.ai_confidence,'ai_reason',t.ai_reason,'organize_op_id',t.organize_op_id,'version',t.version) where id=op;
    applied := applied||t.id;
  end loop;
  return jsonb_build_object('applied',cardinality(applied),'transactionIds',to_jsonb(applied),'skipped',skipped);
end;
$$;
revoke all on function public.apply_ai_organization(uuid,uuid,jsonb,uuid) from public,anon,authenticated;
grant execute on function public.apply_ai_organization(uuid,uuid,jsonb,uuid) to service_role;

-- The owner's Undo for AI labels. A row is restored only while it still holds exactly what that op
-- wrote (an import that bumps the version does not block it; an owner edit does). Undone
-- suggestions are suppressed for the same identity; a different suggestion is still allowed.
create function public.undo_ai_organization(p_op_ids uuid[])
returns jsonb language plpgsql security definer set search_path='' as $$
declare op public.organizer_ops%rowtype; t public.transactions%rowtype; undone integer:=0; skipped integer:=0;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if p_op_ids is null or cardinality(p_op_ids) not between 1 and 500 then raise exception 'Choose AI changes to undo' using errcode='22023'; end if;
  if (select count(*) from public.organizer_ops where id=any(p_op_ids) and public.owns_workspace(workspace_id))<>(select count(distinct id) from unnest(p_op_ids) id)
    then raise exception 'AI change not found' using errcode='P0002'; end if;
  perform 1 from public.transactions where id in(select transaction_id from public.organizer_ops where id=any(p_op_ids)) order by id for update;
  for op in select * from public.organizer_ops where id=any(p_op_ids) order by transaction_id,created_at desc for update loop
    if op.undone_at is not null then continue; end if;
    select * into t from public.transactions where id=op.transaction_id and workspace_id=op.workspace_id;
    if t.organize_op_id is distinct from op.id or t.category_id is distinct from (op.after->>'category_id')::uuid
      or t.merchant_id is distinct from (op.after->>'merchant_id')::uuid
      or exists(select 1 from public.transaction_split_sets s where s.transaction_id=t.id and s.undone_at is null) then
      skipped := skipped+1; continue;
    end if;
    update public.transactions set category_id=(op.before->>'category_id')::uuid,merchant_id=(op.before->>'merchant_id')::uuid,
      organized_by=op.before->>'organized_by',ai_confidence=op.before->>'ai_confidence',ai_reason=op.before->>'ai_reason',
      organize_op_id=(op.before->>'organize_op_id')::uuid,version=version+1 where id=t.id;
    update public.organizer_ops set undone_at=now(),suppressed=true where id=op.id;
    undone := undone+1;
  end loop;
  return jsonb_build_object('undone',undone,'skipped',skipped);
end;
$$;
revoke all on function public.undo_ai_organization(uuid[]) from public,anon;
grant execute on function public.undo_ai_organization(uuid[]) to authenticated;

-- The old path stored AI guesses as the owner's corrections and rules.
drop function public.auto_apply_organization_review(uuid,jsonb,jsonb,text,text,jsonb,uuid);

-- Takes back what the old auto-apply did, row by row, keeping anything the owner changed since:
-- * a row is restored (and its event undone) unless a later correction is still active, its labels
--   no longer match the event's `after`, or it was split; an event left in place is stamped 'ai';
-- * a saved rule still exactly as the review left it is deleted (new) or restored (existing);
--   a rule the owner edited since is kept;
-- * merchants those reviews created and nothing uses any more are deleted, the rest marked 'ai';
-- * the proposals are rejected with {reset: true}; the hourly backlog check reorganizes the rows.
create function public.reset_auto_organization() returns jsonb language plpgsql security definer set search_path='' as $$
declare
  review public.organization_reviews%rowtype; event public.correction_events%rowtype; t public.transactions%rowtype; current_rule public.organization_rules%rowtype;
  proposals uuid[]; touched_rules uuid[]:='{}'; merchant_ids uuid[]:='{}'; merchant uuid;
  restored integer:=0; kept integer:=0; rules_deleted integer:=0; rules_restored integer:=0; rules_kept integer:=0; merchants_deleted integer:=0;
begin
  select coalesce(array_agg(p.id),'{}') into proposals from public.agent_proposals p where p.kind='categorize'
    and (p.result->>'auto'='true' or (p.status in ('applying','failed') and exists(select 1 from public.organization_reviews r where r.workspace_id=p.workspace_id and r.request_id=p.id)));
  -- Newest first, so a review that built on an earlier one is taken back before it.
  for review in select r.* from public.organization_reviews r join public.agent_proposals p on p.id=r.request_id and p.workspace_id=r.workspace_id
    where p.id=any(proposals) and r.batch_id is not null order by r.created_at desc,r.id desc for update of r loop
    for event in select * from public.correction_events where workspace_id=review.workspace_id and after->>'batch_id'=review.batch_id::text
      and after->>'operation'='metadata' and not undone order by transaction_id for update loop
      select * into t from public.transactions where id=event.transaction_id and workspace_id=event.workspace_id for update;
      if exists(select 1 from public.correction_events later where later.transaction_id=event.transaction_id and later.id<>event.id and not later.undone
          and (later.after->>'version')::integer>(event.after->>'version')::integer)
        or t.category_id is distinct from (event.after->>'category_id')::uuid
        or (event.after ? 'merchant_id' and t.merchant_id is distinct from (event.after->>'merchant_id')::uuid)
        or exists(select 1 from public.transaction_split_sets s where s.transaction_id=t.id and s.undone_at is null) then
        update public.correction_events set origin='ai' where id=event.id;
        kept := kept+1;
      else
        update public.transactions set category_id=(event.before->>'category_id')::uuid,
          merchant_id=case when event.before ? 'merchant_id' then (event.before->>'merchant_id')::uuid else merchant_id end,version=version+1 where id=t.id;
        update public.correction_events set undone=true where id=event.id;
        restored := restored+1;
      end if;
    end loop;
    update public.transaction_batches set undone=true where id=review.batch_id;
    if review.saved_rule_id is not null and review.saved_rule_after is not null then
      select * into current_rule from public.organization_rules where id=review.saved_rule_id for update;
      if found and (current_rule.version=(review.saved_rule_after->>'version')::integer or current_rule.id=any(touched_rules))
        and (current_rule.merchant_id,current_rule.category_id,current_rule.enabled) is not distinct from
          ((review.saved_rule_after->>'merchant_id')::uuid,(review.saved_rule_after->>'category_id')::uuid,(review.saved_rule_after->>'enabled')::boolean) then
        if review.saved_rule_before is null then
          update public.organization_reviews set saved_rule_id=null where saved_rule_id=current_rule.id;
          delete from public.organization_rules where id=current_rule.id;
          rules_deleted := rules_deleted+1;
        else
          update public.organization_rules set merchant_id=(review.saved_rule_before->>'merchant_id')::uuid,category_id=(review.saved_rule_before->>'category_id')::uuid,
            enabled=(review.saved_rule_before->>'enabled')::boolean,approved_by=(review.saved_rule_before->>'approved_by')::uuid,version=version+1,updated_at=now() where id=current_rule.id;
          touched_rules := touched_rules||current_rule.id;
          rules_restored := rules_restored+1;
        end if;
      elsif found then rules_kept := rules_kept+1;
      end if;
    end if;
    if review.merchant_name is not null then
      merchant_ids := merchant_ids||coalesce((select array_agg(m.id) from public.merchants m where m.workspace_id=review.workspace_id
        and m.normalized_name=lower(regexp_replace(review.merchant_name,'\s+',' ','g')) and m.created_at>=review.created_at),'{}');
    end if;
  end loop;
  foreach merchant in array merchant_ids loop
    if exists(select 1 from public.transactions where merchant_id=merchant) or exists(select 1 from public.organization_rules where merchant_id=merchant) then
      update public.merchants set created_by='ai' where id=merchant;
      continue;
    end if;
    begin
      delete from public.merchants where id=merchant;
      merchants_deleted := merchants_deleted+(case when found then 1 else 0 end);
    exception when foreign_key_violation then
      update public.merchants set created_by='ai' where id=merchant;
    end;
  end loop;
  update public.agent_proposals set status='rejected',result=jsonb_build_object('reset',true),decided_at=coalesce(decided_at,now()) where id=any(proposals);
  return jsonb_build_object('proposals',cardinality(proposals),'restored',restored,'kept',kept,'rulesDeleted',rules_deleted,
    'rulesRestored',rules_restored,'rulesKept',rules_kept,'merchantsDeleted',merchants_deleted);
end;
$$;
revoke all on function public.reset_auto_organization() from public,anon,authenticated;
select public.reset_auto_organization();

"use workflow";

import { createHash } from "node:crypto";
import { serviceClient } from "@/lib/service-db";
import { inspectRows, mappingSchema, parseCsv, parseExcel, parseLegacyExcel } from "@/lib/import/csv";
import { stableId } from "@/lib/import/row";
import { linkOwnTransfers } from "@/lib/finance/own-transfers";
import { batchDecisions, candidateRowsSchema, stageImportRows } from "@/lib/import/batch";
import { startAgentRun } from "@/lib/ai/agent-dispatch";
import { maybeStartFirstReview as startFirstReviewIfFirst } from "@/lib/import/follow-up";

function checked<T>(result: { data: T | null; error: { message: string } | null }): T | null {
  if (result.error) throw new Error(result.error.message);
  return result.data;
}

// followUps is false for a bank sync, which starts the agent team and first review once for all its accounts.
export async function importFile(importId: string, workspaceId: string, rowCount: number, runVersion = 1, followUps = true) {
  "use workflow";
  try {
    const stagedRows = rowCount === 0 ? 0 : await prepareImport(importId, workspaceId, rowCount, runVersion);
    for (let offset = 0; offset < stagedRows; offset += 250) {
      await processImportBatch(importId, workspaceId, offset, runVersion);
    }
    if (!await finishImport(importId, workspaceId, runVersion)) return;
  } catch (error) {
    await failImport(importId, workspaceId, String(error), runVersion);
    return;
  }
  await linkOwnTransfersStep(workspaceId);
  if (!followUps) return;
  await startAgentTeam(importId, workspaceId);
  await maybeStartFirstReview(importId, workspaceId);
}

// Transfers between the owner's own accounts are linked as soon as new rows land, so a later
// import from the other bank completes the pair. A failure never affects the completed import.
async function linkOwnTransfersStep(workspaceId: string) {
  "use step";
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL) return;
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
  try { await linkOwnTransfers(db, workspaceId); } catch (error) { console.error("Own-account transfers were not linked", error); } // The next import retries.
}

// The agent team starts the moment an import's rows are in. It only proposes;
// a failure here never affects the completed import.
async function startAgentTeam(importId: string, workspaceId: string) {
  "use step";
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL) return;
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
  try {
    const imported = checked(await db.from("imports").select("new_rows").eq("id", importId).eq("workspace_id", workspaceId).single()) as { new_rows: number | null };
    if (imported.new_rows) await startAgentRun(db, workspaceId, { importId });
  } catch (error) { console.error("Agent team did not start", error); } // Owners can start it from /ai/agents.
}

async function prepareImport(importId: string, workspaceId: string, rowCount: number, runVersion: number) {
  "use step";
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new Error("Supabase import service is not configured");
  const db = serviceClient(url, key);
  const imported = checked(await db.from("imports").select("*").eq("id", importId).eq("workspace_id", workspaceId).single()) as { status: string; run_version: number; source_id?: string | null; route_accounts?: Record<string, string>; storage_path: string; file_hash: string; mapping: unknown };
  if (imported.status === "completed") return 0;
  if (!["queued", "running"].includes(imported.status) || imported.run_version !== runVersion) throw new Error("Import worker canceled or superseded");
  const stagedCount = checked(await db.rpc("read_import_stage", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion }));
  if (stagedCount !== null) {
    if (stagedCount !== rowCount) throw new Error("Normalized import coverage differs from reviewed rows");
    return rowCount;
  }
  if (!imported.storage_path.startsWith(`${workspaceId}/`)) throw new Error("Import file is outside the workspace");
  const blob = checked(await db.storage.from("imports").download(imported.storage_path));
    if (!blob) throw new Error("Stored import file is missing");
    if (blob.size > 10_000_000) throw new Error("Stored import file exceeds the 10 MB limit");
    const bytes = await blob.arrayBuffer();
    if (createHash("sha256").update(new Uint8Array(bytes)).digest("hex") !== imported.file_hash) throw new Error("Stored import file differs from the reviewed original");
    const extension = imported.storage_path.split(".").pop();
    const confirmedMapping = mappingSchema.parse(imported.mapping);
    const rows = extension === "csv" ? parseCsv(new TextDecoder().decode(bytes)) : confirmedMapping.workbookScope ? await parseExcel(bytes, confirmedMapping.workbookScope) : await parseLegacyExcel(bytes);
    const { mapped, unresolvedRows, excludedRows } = inspectRows(rows, imported.mapping);
    if (unresolvedRows.length) throw new Error(unresolvedRows[0].message);
    const accountIds = new Map<string, string>();
    let preparedSourceId = imported.source_id ?? null;
    const frozenAccounts = new Map(Object.entries(imported.route_accounts ?? {}).map(([route, accountId]) => [JSON.stringify(JSON.parse(route)), accountId]));
    const legacyPrepared = frozenAccounts.size === 0 && !!imported.source_id;
    if (legacyPrepared) {
      const firstSource = checked(await db.from("data_sources").select("account_id").eq("workspace_id", workspaceId).eq("id", imported.source_id!).eq("kind", "file").single()) as { account_id: string | null };
      if (!firstSource.account_id || !mapped[0]) throw new Error("Legacy import route evidence is unavailable");
      frozenAccounts.set(JSON.stringify([mapped[0].accountName, mapped[0].currencyCode]), firstSource.account_id);
      const byNumber = new Map(mapped.map(row => [row.rowNumber, row]));
      type LegacySource = { row_number: number; transaction_sources: { transactions: { account_id: string } | null }[] | { transactions: { account_id: string } | null } | null };
      for (let offset = 0; ; offset += 500) {
        const sources = checked(await db.from("source_transactions").select("row_number, transaction_sources(transactions(account_id))").eq("workspace_id", workspaceId).eq("import_id", importId).order("id").range(offset, offset + 499)) as unknown as LegacySource[];
        for (const source of sources) {
          const mappedRow = byNumber.get(source.row_number);
          const links = Array.isArray(source.transaction_sources) ? source.transaction_sources : [source.transaction_sources];
          for (const link of links) if (link?.transactions?.account_id) {
            if (!mappedRow) throw new Error("Legacy source row differs from the reviewed file");
            const route = JSON.stringify([mappedRow.accountName, mappedRow.currencyCode]);
            if (frozenAccounts.has(route) && frozenAccounts.get(route) !== link.transactions.account_id) throw new Error("Legacy import route has conflicting account evidence");
            frozenAccounts.set(route, link.transactions.account_id);
          }
        }
        if (sources.length < 500) break;
      }
    }
    for (const row of mapped) {
      const routeKey = JSON.stringify([row.accountName, row.currencyCode]);
      if (accountIds.has(routeKey)) continue;
      const frozenAccountId = frozenAccounts.get(routeKey);
      if (legacyPrepared && !frozenAccountId) throw new Error("Legacy partial import route needs review before resume");
      let accountQuery = db.from("accounts").select("id, archived_at").eq("workspace_id", workspaceId).eq("currency_code", row.currencyCode);
      accountQuery = frozenAccountId ? accountQuery.eq("id", frozenAccountId) : accountQuery.eq("name", row.accountName);
      const existingAccount = checked(await accountQuery.limit(2))!;
      if (existingAccount.length > 1) throw new Error("Reviewed import account is ambiguous");
      if (frozenAccountId && !existingAccount.length) throw new Error("Frozen import account unavailable; review the destination before resume");
      if (existingAccount[0]?.archived_at) throw new Error("Archived accounts cannot receive new imports");
      const accountId = frozenAccountId ?? existingAccount[0]?.id ?? stableId(`${workspaceId}:account:${row.accountName}:${row.currencyCode}`);
      accountIds.set(routeKey, accountId);
      const sourceId = stableId(`${workspaceId}:source:${accountId}`);
      preparedSourceId ??= sourceId;
      checked(await db.rpc("prepare_import_route", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion,
        p_account_id: accountId, p_source_id: sourceId, p_account_name: row.accountName, p_currency_code: row.currencyCode, p_total_rows: rows.length }));
    }

    const stagedRows = stageImportRows(workspaceId, importId, mapped, excludedRows, accountIds, rowCount);
    checked(await db.rpc("stage_import_rows", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_file_hash: imported.file_hash,
      p_mapping: imported.mapping, p_routes: imported.route_accounts ?? {}, p_source_id: preparedSourceId, p_rows: stagedRows }));
    return rowCount;
}

async function processImportBatch(importId: string, workspaceId: string, offset: number, runVersion: number) {
  "use step";
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  // Retry stale candidate evidence inside the same durable step. Every attempt
  // rereads candidates and every batch transaction fences canceled/old workers.
  for (let attempt = 0; attempt < 3; attempt++) {
    const candidates = checked(await db.rpc("import_batch_candidates", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_offset: offset }));
    const decisions = batchDecisions(candidateRowsSchema.parse(candidates));
    const result = await db.rpc("ingest_import_batch", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_offset: offset, p_decisions: decisions });
    if (!result.error) return;
    if (result.error.code !== "PT409" || attempt === 2) throw new Error(result.error.message);
  }
}

async function finishImport(importId: string, workspaceId: string, runVersion: number) {
  "use step";
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  return checked(await db.rpc("finish_import_run", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_error: null })) === "completed";
}

async function failImport(importId: string, workspaceId: string, error: string, runVersion: number) {
  "use step";
  const db = serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  checked(await db.rpc("finish_import_run", { p_import_id: importId, p_workspace_id: workspaceId, p_run_version: runVersion, p_error: error }));
}

// Keeps its step name so imports already running when Moneo updates resume cleanly.
async function maybeStartFirstReview(importId: string, workspaceId: string) {
  "use step";
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL) return;
  await startFirstReviewIfFirst(serviceClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY), workspaceId, [importId]);
}
import {z} from 'zod';

const rowSchema = z.object({id: z.uuid(), version: z.number().int().min(0).max(2147483647), description: z.string().min(1).max(1000),
  merchantId: z.uuid().nullable(), categoryId: z.uuid().nullable(), kind: z.enum(['ordinary', 'refund', 'transfer']),
  reviewReasons: z.array(z.string().max(200)).max(20), userCorrected: z.boolean()}).strict();
/** Every saved Apply teaches a rule, so a workspace collects many; suggestions read all of them up to this bound. */
export const MAX_ORGANIZATION_RULES = 2000;
export const organizationRuleSchema = z.object({id: z.uuid(), version: z.number().int().min(1), descriptionKey: z.string().min(3).max(1000),
  merchantId: z.uuid().nullable(), categoryId: z.uuid().nullable(), approvedBy: z.uuid(), enabled: z.boolean()}).strict();
export type OrganizationRow = z.infer<typeof rowSchema>;
export type OrganizationRule = z.infer<typeof organizationRuleSchema>;
export type OrganizationProposal = {transactionId: string; version: number; descriptionKey: string; merchantId: string | null; categoryId: string | null;
  merchantName: string | null; basis: 'approved-rule' | 'consistent-history' | 'review-required' | 'provider-suggestion'; financialReviewRequired: boolean; evidence: {id: string; version: number}[];
  rule?: {id: string; version: number}; evidenceQuote?: string};
export const organizationSuggestionsSchema = z.array(z.object({transactionId: z.uuid(), merchantName: z.string().trim().min(1).max(100).nullable(),
  categoryId: z.uuid().nullable(), evidenceQuote: z.string().min(1).max(100)}).strict()).max(50)
  .refine(values => new Set(values.map(value => value.transactionId)).size === values.length);

export function mergeOrganizationSuggestions(rows: OrganizationRow[], proposals: OrganizationProposal[], input: unknown, categoryIds: string[]): OrganizationProposal[] {
  const suggestions = organizationSuggestionsSchema.parse(input);
  const byId = new Map(rows.map(row => [row.id, row]));
  const ownedCategories = new Set(categoryIds);
  for (const suggestion of suggestions) {
    const row = byId.get(suggestion.transactionId);
    if (!row || row.userCorrected || !proposals.some(proposal => proposal.transactionId === row.id) ||
      !row.description.includes(suggestion.evidenceQuote) || (suggestion.categoryId && !ownedCategories.has(suggestion.categoryId)))
      throw new Error('Suggestion requires the selected unchanged source and an owned category');
  }
  const bySuggestion = new Map(suggestions.map(suggestion => [suggestion.transactionId, suggestion]));
  return proposals.map(proposal => {
    const suggestion = bySuggestion.get(proposal.transactionId);
    if (!suggestion || proposal.basis !== 'review-required') return proposal;
    return {...proposal, categoryId: proposal.categoryId ?? suggestion.categoryId,
      merchantName: proposal.merchantId ? null : suggestion.merchantName ?? proposal.merchantName,
      basis: 'provider-suggestion', evidenceQuote: suggestion.evidenceQuote};
  });
}

/**
 * What a payment is "from" for matching: bank text without dates, amounts, IBANs, reference numbers or the trailing SEPA
 * fields, each word once. Monthly payments whose bank text differs only in those details share one key, so one rule covers them.
 */
export function organizationDescriptionKey(description: string) {
  const words = description.normalize('NFKC')
    .replace(/\b[A-Z]{6}[A-Z0-9]{2}(?:[A-Z0-9]{3})?\s+[A-Z]{2}\d{2}[A-Z0-9]{10,30}\b/gu, ' ')
    .toLocaleLowerCase('en')
    .replace(/(?:end-to-end-ref|kundenreferenz|mandatsref|gläubiger-id|sepa-basislastschrift|\d{4}-\d{2}-\d{2}t\d).*$/su, ' ')
    .replace(/\b(?:ref(?:erence)?|invoice|order|receipt|terminal)\b\s*[:#-]?\s*[a-z0-9-]*\d[a-z0-9-]*\b/gu, ' ')
    .replace(/^\s*(?:(?:card payment|pos purchase|card purchase)\s+)+/u, '')
    .split(/[^\p{L}\p{N}]+/u).filter(Boolean);
  // Words with digits are dates and references, and single letters are leftovers like "D" or "K"; a name made only of them ("O2", "H&M") keeps them.
  const named = words.filter(word => word.length > 1 && !/\d/u.test(word));
  return [...new Set(named.length ? named : words.filter(word => /\p{L}/u.test(word)))].join(' ');
}

/** A person-facing name for a matching key: the first few words, capitalized, instead of the bank's raw text. */
export function organizationDisplayName(key: string) {
  const words = key.split(' ').filter(Boolean);
  const name = words.slice(0, 5).map(word => word[0].toLocaleUpperCase('de') + word.slice(1)).join(' ');
  return words.length > 5 ? name + '…' : name;
}

export function organizationProposals(rows: OrganizationRow[], history: OrganizationRow[], rules: OrganizationRule[]): OrganizationProposal[] {
  z.array(rowSchema).max(50).refine(values => new Set(values.map(row => row.id)).size === values.length).parse(rows);
  z.array(rowSchema).max(2000).refine(values => new Set(values.map(row => row.id)).size === values.length).parse(history);
  z.array(organizationRuleSchema).max(MAX_ORGANIZATION_RULES).refine(values => new Set(values.filter(rule => rule.enabled).map(rule => rule.descriptionKey)).size === values.filter(rule => rule.enabled).length).parse(rules);
  const approved = new Map(rules.filter(rule => rule.enabled).map(rule => [rule.descriptionKey, rule]));
  const grouped = new Map<string, OrganizationRow[]>();
  for (const row of history) {
    const key = organizationDescriptionKey(row.description);
    if (key.length < 3 || row.kind !== 'ordinary' || row.reviewReasons.length) continue;
    const entries = grouped.get(key) ?? []; entries.push(row); grouped.set(key, entries);
  }
  const proposals: OrganizationProposal[] = [];
  for (const row of rows) {
    if (row.userCorrected || (row.merchantId && row.categoryId)) continue;
    const descriptionKey = organizationDescriptionKey(row.description), rule = approved.get(descriptionKey);
    const evidence = (grouped.get(descriptionKey) ?? []).filter(value => value.id !== row.id).sort((a, b) => a.id.localeCompare(b.id));
    const merchants = new Set(evidence.map(value => value.merchantId));
    const categories = new Set(evidence.map(value => value.categoryId));
    const merchantId = evidence.length >= 3 && merchants.size === 1 ? evidence[0].merchantId : null;
    const categoryId = evidence.length >= 3 && categories.size === 1 ? evidence[0].categoryId : null;
    proposals.push({transactionId: row.id, version: row.version, descriptionKey,
      merchantId: row.merchantId ?? rule?.merchantId ?? merchantId, categoryId: row.categoryId ?? rule?.categoryId ?? categoryId,
      merchantName: row.merchantId || rule?.merchantId || merchantId || descriptionKey.length < 3 || row.reviewReasons.length || row.kind === 'transfer' ? null : Array.from(descriptionKey).slice(0, 100).join(''),
      basis: rule ? 'approved-rule' : merchantId && categoryId ? 'consistent-history' : 'review-required',
      financialReviewRequired: row.reviewReasons.length > 0 || row.kind === 'transfer',
      evidence: evidence.map(value => ({id: value.id, version: value.version})), ...(rule ? {rule: {id: rule.id, version: rule.version}} : {})});
  }
  return proposals.sort((a, b) => Number(b.financialReviewRequired) - Number(a.financialReviewRequired) || a.transactionId.localeCompare(b.transactionId));
}
-- The bank's full transaction beside the 8-column statement CSV (which must never change: its bytes are the dedupe hash).
-- One row per CSV row, keyed like source_transactions (import_id, row_number). The normalized columns are generic
-- (any bank on Enable Banking) context for the organizer; they never feed ledger amounts. Written by the bank sync
-- (service role); the owner can read it. Removed with its import on undo, and on reset.
create table public.bank_transaction_raw (
  import_id uuid not null references public.imports(id) on delete cascade,
  row_number integer not null check (row_number >= 2),
  workspace_id uuid not null references public.workspaces(id),
  bank_id text check (char_length(bank_id) <= 500),
  raw jsonb not null default '{}' check (jsonb_typeof(raw) = 'object' and octet_length(raw::text) <= 65536),
  payment_type text not null default 'unknown' check (payment_type in ('card','transfer','direct_debit','cash','fee_interest','top_up','exchange','unknown')),
  bank_code text check (char_length(bank_code) <= 200),
  bank_sub_code text check (char_length(bank_sub_code) <= 200),
  mcc text check (char_length(mcc) <= 10),
  counterparty_name text check (char_length(counterparty_name) <= 500),
  counterparty_iban text check (char_length(counterparty_iban) <= 34),
  counterparty_bic text check (char_length(counterparty_bic) <= 11),
  counterparty_ids jsonb not null default '[]' check (jsonb_typeof(counterparty_ids) = 'array' and octet_length(counterparty_ids::text) <= 8192),
  own_side_ids jsonb not null default '[]' check (jsonb_typeof(own_side_ids) = 'array' and octet_length(own_side_ids::text) <= 8192),
  creditor_id text check (char_length(creditor_id) <= 40),
  mandate_ref text check (char_length(mandate_ref) <= 40),
  -- Context only, as the bank states them: never used for ledger amounts.
  instructed_amount text check (char_length(instructed_amount) <= 40),
  instructed_currency text check (instructed_currency ~ '^[A-Z]{3}$'),
  exchange_rate text check (char_length(exchange_rate) <= 40),
  own_account boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (import_id, row_number)
);
create index bank_transaction_raw_workspace_idx on public.bank_transaction_raw(workspace_id);

alter table public.bank_transaction_raw enable row level security;
create policy bank_transaction_raw_owned on public.bank_transaction_raw for select using (public.owns_workspace(workspace_id));
revoke all on public.bank_transaction_raw from anon, authenticated;
grant select on public.bank_transaction_raw to authenticated;
grant all on public.bank_transaction_raw to service_role;

-- Undoing an import removes the rows it brought, and so the bank data kept for them. (The import row stays as history;
-- a later sync of the same window makes a new import and writes its own rows.)
create function public.remove_undone_bank_raw() returns trigger language plpgsql security definer set search_path='' as $$
begin
  delete from public.bank_transaction_raw where import_id = new.id;
  return new;
end;
$$;
revoke all on function public.remove_undone_bank_raw() from public, anon, authenticated;
create trigger imports_remove_bank_raw after update of status on public.imports
  for each row when (new.status = 'undone' and old.status is distinct from 'undone') execute function public.remove_undone_bank_raw();

create or replace function public.reset_workspace() returns void language plpgsql security definer set search_path='' as $$
declare ws uuid; owner uuid := auth.uid();
begin
  if owner is null then raise exception 'Unauthorized' using errcode='42501'; end if;
  select id into ws from public.workspaces where owner_id=owner for update;
  if not found then raise exception 'Workspace unavailable' using errcode='P0002'; end if;
  -- Deleted history is not undoable, so skip planning audit rows and link-edit guards.
  perform set_config('moneo.planning_undo','true',true);
  perform set_config('moneo.link_edit','on',true);

  -- Agent team runs, tasks and proposals.
  delete from public.agent_proposals where workspace_id=ws;
  delete from public.agent_tasks where workspace_id=ws;
  delete from public.agent_runs where workspace_id=ws;

  -- AI conversations and reviews.
  delete from public.saved_analyses where workspace_id=ws;
  delete from public.summary_runs where workspace_id=ws;
  delete from public.background_jobs where workspace_id=ws;
  delete from public.chat_requests where workspace_id=ws;
  delete from public.messages where workspace_id=ws;
  delete from public.conversations where workspace_id=ws;
  delete from public.dashboard_layouts where workspace_id=ws;

  -- Preferences, views and settings.
  delete from public.insight_dismissals where workspace_id=ws;
  delete from public.insight_preferences where workspace_id=ws;
  delete from public.financial_evidence_receipts where workspace_id=ws;
  delete from public.transaction_views where workspace_id=ws;
  delete from public.fx_rates where workspace_id=ws;
  delete from public.workspace_settings where workspace_id=ws;

  -- Everything that points at transactions.
  delete from public.transaction_link_fees where workspace_id=ws;
  delete from public.transaction_links where workspace_id=ws;
  delete from public.transaction_splits where workspace_id=ws;
  delete from public.transaction_split_sets where workspace_id=ws;
  delete from public.pending_hold_resolutions where workspace_id=ws;
  delete from public.correction_events where workspace_id=ws;
  delete from public.recurring_occurrence_settlements where workspace_id=ws;
  delete from public.recurring_series_transactions where workspace_id=ws;
  delete from public.recurring_series where workspace_id=ws;
  delete from public.manual_transaction_entries where workspace_id=ws;
  delete from public.money_metadata_events where workspace_id=ws;
  delete from public.organization_reviews where workspace_id=ws;
  delete from public.organization_rules where workspace_id=ws;
  delete from public.transaction_batches where workspace_id=ws;
  delete from public.scalable_value_history where workspace_id=ws;
  delete from public.wealth_events where workspace_id=ws;
  delete from public.wealth_items where workspace_id=ws;
  delete from public.transaction_sources where transaction_id in (select id from public.transactions where workspace_id=ws)
    or source_transaction_id in (select id from public.source_transactions where workspace_id=ws);
  delete from public.balance_snapshots where workspace_id=ws;
  update public.transactions set transfer_id=null, refund_of_id=null
    where workspace_id=ws and (transfer_id is not null or refund_of_id is not null);
  delete from public.transactions where workspace_id=ws;

  delete from public.bank_transaction_raw where workspace_id=ws;

  -- Bank connections, then imports.
  delete from public.bank_connection_accounts where workspace_id=ws;
  delete from public.bank_connections where workspace_id=ws;

  -- Imports.
  delete from public.source_transactions where workspace_id=ws;
  delete from public.import_control_events where workspace_id=ws;
  delete from public.import_staging where workspace_id=ws;
  delete from public.imports where workspace_id=ws;
  delete from public.data_sources where workspace_id=ws;

  -- Goals, plans, scenarios and budgets.
  delete from public.goal_reservation_events where workspace_id=ws;
  delete from public.goal_allocations where workspace_id=ws;
  delete from public.goal_events where workspace_id=ws;
  delete from public.goals where workspace_id=ws;
  delete from public.forecast_runs where workspace_id=ws;
  delete from public.scenario_overrides where workspace_id=ws;
  delete from public.scenario_events where workspace_id=ws;
  delete from public.scenarios where workspace_id=ws;
  delete from public.spending_plan_limits where workspace_id=ws;
  delete from public.spending_plans where workspace_id=ws;
  delete from public.financial_assumptions where workspace_id=ws;
  delete from public.planning_events where workspace_id=ws;
  delete from public.forecast_preference_events where workspace_id=ws;
  delete from public.forecast_preferences where workspace_id=ws;

  -- Remaining parents, then a fresh workspace exactly like create_private_workspace().
  delete from public.merchants where workspace_id=ws;
  delete from public.categories where workspace_id=ws;
  delete from public.accounts where workspace_id=ws;
  delete from public.workspaces where id=ws;
  insert into public.workspaces(owner_id) values(owner);
end;
$$;

-- AI organization labels get their own provenance. The organizer writes category and merchant labels
-- itself (the one AI write without a card), marked as AI and logged in organizer_ops for Undo. They
-- never become owner corrections or organization rules, so they never count as evidence either.

-- Who set a row's labels: null = not organized yet (or before this migration).
alter table public.transactions add column organized_by text check (organized_by in ('owner','rule','memory','ai','system'));
alter table public.transactions add column ai_confidence text check (ai_confidence in ('high','medium','low'));
alter table public.transactions add column ai_reason text check (char_length(ai_reason) <= 500);
alter table public.transactions add column organize_op_id uuid;

-- Events the old auto-apply left behind are stamped 'ai' so they never count as owner corrections.
alter table public.correction_events add column origin text not null default 'owner' check (origin in ('owner','ai'));

-- Later the AI may change only categories and merchants it made and the owner never used.
alter table public.categories add column created_by text not null default 'owner' check (created_by in ('owner','ai'));
alter table public.categories add column owner_touched boolean not null default false;
alter table public.merchants add column created_by text not null default 'owner' check (created_by in ('owner','ai'));
alter table public.merchants add column owner_touched boolean not null default false;

-- One row per AI label write: the Undo record and, once undone, a "don't suggest this again" marker
-- for (identity_key, category or merchant). identity_key is today's organization description key.
create table public.organizer_ops (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  run_id uuid references public.agent_runs(id) on delete set null,
  proposal_id uuid references public.agent_proposals(id) on delete set null,
  transaction_id uuid not null references public.transactions(id) on delete cascade,
  identity_key text not null check (char_length(identity_key) <= 1000),
  category_id uuid,
  merchant_id uuid,
  before jsonb not null,
  after jsonb not null,
  created_at timestamptz not null default now(),
  undone_at timestamptz,
  suppressed boolean not null default false,
  check (category_id is not null or merchant_id is not null)
);
create index organizer_ops_workspace_created on public.organizer_ops(workspace_id, created_at desc);
create index organizer_ops_transaction on public.organizer_ops(transaction_id);
create index organizer_ops_proposal on public.organizer_ops(proposal_id) where proposal_id is not null;
create index organizer_ops_suppressed on public.organizer_ops(workspace_id, identity_key) where suppressed;
alter table public.organizer_ops enable row level security;
create policy organizer_ops_owned on public.organizer_ops for select using (public.owns_workspace(workspace_id));
revoke all on public.organizer_ops from anon, authenticated;
grant select on public.organizer_ops to authenticated, service_role;

-- An owner correction that changes a row's category or merchant makes the owner its organizer. The
-- event keeps the previous provenance in `before`, so undoing the edit restores an AI row exactly.
-- Every owner path (quick edit, chat, bulk edit, organization review) writes such an event.
create function public.stamp_owner_organization() returns trigger language plpgsql security definer set search_path='' as $$
declare current_row public.transactions%rowtype; category_changed boolean; merchant_changed boolean;
begin
  if new.origin<>'owner' then return new; end if;
  category_changed := new.before ? 'category_id' and new.after ? 'category_id' and new.before->'category_id' is distinct from new.after->'category_id';
  merchant_changed := new.before ? 'merchant_id' and new.after ? 'merchant_id' and new.before->'merchant_id' is distinct from new.after->'merchant_id';
  if not (category_changed or merchant_changed) then return new; end if;
  select * into current_row from public.transactions where id=new.transaction_id and workspace_id=new.workspace_id;
  if not found then return new; end if;
  new.before := new.before || jsonb_build_object('organized_by',current_row.organized_by,'ai_confidence',current_row.ai_confidence,
    'ai_reason',current_row.ai_reason,'organize_op_id',current_row.organize_op_id);
  new.after := new.after || jsonb_build_object('organized_by','owner','ai_confidence',null,'ai_reason',null,'organize_op_id',null);
  update public.transactions set organized_by='owner',ai_confidence=null,ai_reason=null,organize_op_id=null where id=current_row.id;
  if category_changed and new.after->>'category_id' is not null then
    update public.categories set owner_touched=true where id=(new.after->>'category_id')::uuid and workspace_id=new.workspace_id and not owner_touched;
  end if;
  if merchant_changed and new.after->>'merchant_id' is not null then
    update public.merchants set owner_touched=true where id=(new.after->>'merchant_id')::uuid and workspace_id=new.workspace_id and not owner_touched;
  end if;
  return new;
end;
$$;
create trigger correction_events_owner_organization before insert on public.correction_events for each row execute function public.stamp_owner_organization();

-- Undoing any correction that recorded provenance puts that provenance back with the labels.
create function public.restore_undone_organization() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if new.undone and not old.undone and new.before ? 'organized_by' then
    update public.transactions set organized_by=new.before->>'organized_by',ai_confidence=new.before->>'ai_confidence',
      ai_reason=new.before->>'ai_reason',organize_op_id=(new.before->>'organize_op_id')::uuid
      where id=new.transaction_id and workspace_id=new.workspace_id;
  end if;
  return null;
end;
$$;
create trigger correction_events_restore_organization after update of undone on public.correction_events for each row execute function public.restore_undone_organization();

-- Splitting a row into a category is the owner using that category.
create function public.touch_split_category() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if new.category_id is not null then
    update public.categories set owner_touched=true where id=new.category_id and workspace_id=new.workspace_id and not owner_touched;
  end if;
  return null;
end;
$$;
create trigger transaction_splits_owner_touch after insert on public.transaction_splits for each row execute function public.touch_split_category();
revoke all on function public.stamp_owner_organization(),public.restore_undone_organization(),public.touch_split_category() from public,anon,authenticated;

-- The organizer's write path (service role only). Fills only empty labels, never on rows the owner
-- organized or corrected, split rows, rows changed since the suggestion, or suggestions the owner
-- undid for the same identity. No correction events, no rules, no auth claims.
create function public.apply_ai_organization(p_workspace uuid,p_run uuid,p_items jsonb,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  item jsonb; t public.transactions%rowtype; ids uuid[]; new_category uuid; new_merchant uuid; merchant_name text; normalized text;
  create_merchant boolean; was_suppressed boolean; op uuid; reason text; applied uuid[]:='{}'; skipped jsonb:='{}';
begin
  if p_workspace is null or not exists(select 1 from public.workspaces where id=p_workspace) then raise exception 'Workspace not found' using errcode='P0002'; end if;
  if p_run is not null and not exists(select 1 from public.agent_runs where id=p_run and workspace_id=p_workspace) then raise exception 'Run not found' using errcode='P0002'; end if;
  if p_proposal is not null and not exists(select 1 from public.agent_proposals where id=p_proposal and workspace_id=p_workspace) then raise exception 'Proposal not found' using errcode='P0002'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 500 then raise exception 'Invalid AI organization' using errcode='22023'; end if;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item)<>'object' or item-array['transaction_id','expected_version','category_id','merchant_id','merchant_name','confidence','reason','identity_key']<>'{}'::jsonb
      or jsonb_typeof(item->'transaction_id') is distinct from 'string' or coalesce(item->>'expected_version','') !~ '^[0-9]+$'
      or coalesce(item->>'confidence','') not in ('high','medium','low')
      or jsonb_typeof(item->'identity_key') is distinct from 'string' or char_length(item->>'identity_key')>1000
      or coalesce(jsonb_typeof(item->'reason'),'null') not in ('string','null')
      or coalesce(jsonb_typeof(item->'category_id'),'null') not in ('string','null') or coalesce(jsonb_typeof(item->'merchant_id'),'null') not in ('string','null')
      or coalesce(jsonb_typeof(item->'merchant_name'),'null') not in ('string','null')
      or (item->>'merchant_name' is not null and (char_length(btrim(item->>'merchant_name')) not between 1 and 100 or item->>'merchant_id' is not null))
      or coalesce(item->>'category_id',item->>'merchant_id',item->>'merchant_name') is null
      then raise exception 'Invalid AI organization item' using errcode='22023'; end if;
  end loop;
  select array_agg((value->>'transaction_id')::uuid) into ids from jsonb_array_elements(p_items);
  if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) then raise exception 'Duplicate AI organization row' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_items) i where (i->>'category_id' is not null and not exists(select 1 from public.categories c where c.id=(i->>'category_id')::uuid and c.workspace_id=p_workspace))
    or (i->>'merchant_id' is not null and not exists(select 1 from public.merchants m where m.id=(i->>'merchant_id')::uuid and m.workspace_id=p_workspace)))
    then raise exception 'Organization target not found' using errcode='P0002'; end if;
  -- Same lock order as the owner's bulk edits.
  perform 1 from public.transactions where id=any(ids) and workspace_id=p_workspace order by id for update;
  for item in select value from jsonb_array_elements(p_items) order by value->>'transaction_id' loop
    select * into t from public.transactions where id=(item->>'transaction_id')::uuid and workspace_id=p_workspace;
    reason := null;
    if not found then reason := 'missing';
    elsif item->>'confidence'='low' then reason := 'low_confidence';
    elsif t.version<>(item->>'expected_version')::integer then reason := 'changed';
    elsif t.organized_by='owner' then reason := 'owner';
    elsif exists(select 1 from public.correction_events e where e.transaction_id=t.id and e.workspace_id=p_workspace and not e.undone and e.origin='owner'
      and ((e.before ? 'category_id' and e.after ? 'category_id' and e.before->'category_id' is distinct from e.after->'category_id')
        or (e.before ? 'merchant_id' and e.after ? 'merchant_id' and e.before->'merchant_id' is distinct from e.after->'merchant_id'))) then reason := 'owner_corrected';
    elsif exists(select 1 from public.transaction_split_sets s where s.transaction_id=t.id and s.undone_at is null) then reason := 'split';
    end if;
    if reason is null then
      new_category := case when t.category_id is null then (item->>'category_id')::uuid end;
      new_merchant := null; create_merchant := false; was_suppressed := false; merchant_name := null;
      if t.merchant_id is null and item->>'merchant_id' is not null then new_merchant := (item->>'merchant_id')::uuid;
      elsif t.merchant_id is null and item->>'merchant_name' is not null then
        merchant_name := btrim(item->>'merchant_name'); normalized := lower(regexp_replace(merchant_name,'\s+',' ','g'));
        select id into new_merchant from public.merchants where workspace_id=p_workspace and normalized_name=normalized;
        create_merchant := new_merchant is null;
      end if;
      if new_category is not null and exists(select 1 from public.organizer_ops o where o.workspace_id=p_workspace and o.suppressed
        and o.identity_key=item->>'identity_key' and o.category_id=new_category) then new_category := null; was_suppressed := true; end if;
      if new_merchant is not null and exists(select 1 from public.organizer_ops o where o.workspace_id=p_workspace and o.suppressed
        and o.identity_key=item->>'identity_key' and o.merchant_id=new_merchant) then new_merchant := null; was_suppressed := true; end if;
      if new_category is null and new_merchant is null and not create_merchant then reason := case when was_suppressed then 'suppressed' else 'labelled' end; end if;
    end if;
    if reason is not null then
      skipped := jsonb_set(skipped,array[reason],to_jsonb(coalesce((skipped->>reason)::integer,0)+1));
      continue;
    end if;
    if create_merchant then
      insert into public.merchants(workspace_id,name,normalized_name,created_by) values(p_workspace,merchant_name,normalized,'ai') on conflict(workspace_id,normalized_name) do nothing;
      select id into strict new_merchant from public.merchants where workspace_id=p_workspace and normalized_name=normalized;
    end if;
    insert into public.organizer_ops(workspace_id,run_id,proposal_id,transaction_id,identity_key,category_id,merchant_id,before,after)
      values(p_workspace,p_run,p_proposal,t.id,item->>'identity_key',new_category,new_merchant,
        jsonb_build_object('category_id',t.category_id,'merchant_id',t.merchant_id,'organized_by',t.organized_by,'ai_confidence',t.ai_confidence,
          'ai_reason',t.ai_reason,'organize_op_id',t.organize_op_id,'version',t.version),'{}') returning id into op;
    update public.transactions set category_id=coalesce(new_category,category_id),merchant_id=coalesce(new_merchant,merchant_id),
      organized_by='ai',ai_confidence=item->>'confidence',ai_reason=left(nullif(btrim(item->>'reason'),''),500),organize_op_id=op,version=version+1
      where id=t.id returning * into t;
    update public.organizer_ops set after=jsonb_build_object('category_id',t.category_id,'merchant_id',t.merchant_id,'organized_by',t.organized_by,
      'ai_confidence',t.ai_confidence,'ai_reason',t.ai_reason,'organize_op_id',t.organize_op_id,'version',t.version) where id=op;
    applied := applied||t.id;
  end loop;
  return jsonb_build_object('applied',cardinality(applied),'transactionIds',to_jsonb(applied),'skipped',skipped);
end;
$$;
revoke all on function public.apply_ai_organization(uuid,uuid,jsonb,uuid) from public,anon,authenticated;
grant execute on function public.apply_ai_organization(uuid,uuid,jsonb,uuid) to service_role;

-- The owner's Undo for AI labels. A row is restored only while it still holds exactly what that op
-- wrote (an import that bumps the version does not block it; an owner edit does). Undone
-- suggestions are suppressed for the same identity; a different suggestion is still allowed.
create function public.undo_ai_organization(p_op_ids uuid[])
returns jsonb language plpgsql security definer set search_path='' as $$
declare op public.organizer_ops%rowtype; t public.transactions%rowtype; undone integer:=0; skipped integer:=0;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if p_op_ids is null or cardinality(p_op_ids) not between 1 and 500 then raise exception 'Choose AI changes to undo' using errcode='22023'; end if;
  if (select count(*) from public.organizer_ops where id=any(p_op_ids) and public.owns_workspace(workspace_id))<>(select count(distinct id) from unnest(p_op_ids) id)
    then raise exception 'AI change not found' using errcode='P0002'; end if;
  perform 1 from public.transactions where id in(select transaction_id from public.organizer_ops where id=any(p_op_ids)) order by id for update;
  for op in select * from public.organizer_ops where id=any(p_op_ids) order by transaction_id,created_at desc for update loop
    if op.undone_at is not null then continue; end if;
    select * into t from public.transactions where id=op.transaction_id and workspace_id=op.workspace_id;
    if t.organize_op_id is distinct from op.id or t.category_id is distinct from (op.after->>'category_id')::uuid
      or t.merchant_id is distinct from (op.after->>'merchant_id')::uuid
      or exists(select 1 from public.transaction_split_sets s where s.transaction_id=t.id and s.undone_at is null) then
      skipped := skipped+1; continue;
    end if;
    update public.transactions set category_id=(op.before->>'category_id')::uuid,merchant_id=(op.before->>'merchant_id')::uuid,
      organized_by=op.before->>'organized_by',ai_confidence=op.before->>'ai_confidence',ai_reason=op.before->>'ai_reason',
      organize_op_id=(op.before->>'organize_op_id')::uuid,version=version+1 where id=t.id;
    update public.organizer_ops set undone_at=now(),suppressed=true where id=op.id;
    undone := undone+1;
  end loop;
  return jsonb_build_object('undone',undone,'skipped',skipped);
end;
$$;
revoke all on function public.undo_ai_organization(uuid[]) from public,anon;
grant execute on function public.undo_ai_organization(uuid[]) to authenticated;

-- The old path stored AI guesses as the owner's corrections and rules.
drop function public.auto_apply_organization_review(uuid,jsonb,jsonb,text,text,jsonb,uuid);

-- Takes back what the old auto-apply did, row by row, keeping anything the owner changed since:
-- * a row is restored (and its event undone) unless a later correction is still active, its labels
--   no longer match the event's `after`, or it was split; an event left in place is stamped 'ai';
-- * a saved rule still exactly as the review left it is deleted (new) or restored (existing);
--   a rule the owner edited since is kept;
-- * merchants those reviews created and nothing uses any more are deleted, the rest marked 'ai';
-- * the proposals are rejected with {reset: true}; the hourly backlog check reorganizes the rows.
create function public.reset_auto_organization() returns jsonb language plpgsql security definer set search_path='' as $$
declare
  review public.organization_reviews%rowtype; event public.correction_events%rowtype; t public.transactions%rowtype; current_rule public.organization_rules%rowtype;
  proposals uuid[]; touched_rules uuid[]:='{}'; merchant_ids uuid[]:='{}'; merchant uuid;
  restored integer:=0; kept integer:=0; rules_deleted integer:=0; rules_restored integer:=0; rules_kept integer:=0; merchants_deleted integer:=0;
begin
  select coalesce(array_agg(p.id),'{}') into proposals from public.agent_proposals p where p.kind='categorize'
    and (p.result->>'auto'='true' or (p.status in ('applying','failed') and exists(select 1 from public.organization_reviews r where r.workspace_id=p.workspace_id and r.request_id=p.id)));
  -- Newest first, so a review that built on an earlier one is taken back before it.
  for review in select r.* from public.organization_reviews r join public.agent_proposals p on p.id=r.request_id and p.workspace_id=r.workspace_id
    where p.id=any(proposals) and r.batch_id is not null order by r.created_at desc,r.id desc for update of r loop
    for event in select * from public.correction_events where workspace_id=review.workspace_id and after->>'batch_id'=review.batch_id::text
      and after->>'operation'='metadata' and not undone order by transaction_id for update loop
      select * into t from public.transactions where id=event.transaction_id and workspace_id=event.workspace_id for update;
      if exists(select 1 from public.correction_events later where later.transaction_id=event.transaction_id and later.id<>event.id and not later.undone
          and (later.after->>'version')::integer>(event.after->>'version')::integer)
        or t.category_id is distinct from (event.after->>'category_id')::uuid
        or (event.after ? 'merchant_id' and t.merchant_id is distinct from (event.after->>'merchant_id')::uuid)
        or exists(select 1 from public.transaction_split_sets s where s.transaction_id=t.id and s.undone_at is null) then
        update public.correction_events set origin='ai' where id=event.id;
        kept := kept+1;
      else
        update public.transactions set category_id=(event.before->>'category_id')::uuid,
          merchant_id=case when event.before ? 'merchant_id' then (event.before->>'merchant_id')::uuid else merchant_id end,version=version+1 where id=t.id;
        update public.correction_events set undone=true where id=event.id;
        restored := restored+1;
      end if;
    end loop;
    update public.transaction_batches set undone=true where id=review.batch_id;
    if review.saved_rule_id is not null and review.saved_rule_after is not null then
      select * into current_rule from public.organization_rules where id=review.saved_rule_id for update;
      if found and (current_rule.version=(review.saved_rule_after->>'version')::integer or current_rule.id=any(touched_rules))
        and (current_rule.merchant_id,current_rule.category_id,current_rule.enabled) is not distinct from
          ((review.saved_rule_after->>'merchant_id')::uuid,(review.saved_rule_after->>'category_id')::uuid,(review.saved_rule_after->>'enabled')::boolean) then
        if review.saved_rule_before is null then
          update public.organization_reviews set saved_rule_id=null where saved_rule_id=current_rule.id;
          delete from public.organization_rules where id=current_rule.id;
          rules_deleted := rules_deleted+1;
        else
          update public.organization_rules set merchant_id=(review.saved_rule_before->>'merchant_id')::uuid,category_id=(review.saved_rule_before->>'category_id')::uuid,
            enabled=(review.saved_rule_before->>'enabled')::boolean,approved_by=(review.saved_rule_before->>'approved_by')::uuid,version=version+1,updated_at=now() where id=current_rule.id;
          touched_rules := touched_rules||current_rule.id;
          rules_restored := rules_restored+1;
        end if;
      elsif found then rules_kept := rules_kept+1;
      end if;
    end if;
    if review.merchant_name is not null then
      merchant_ids := merchant_ids||coalesce((select array_agg(m.id) from public.merchants m where m.workspace_id=review.workspace_id
        and m.normalized_name=lower(regexp_replace(review.merchant_name,'\s+',' ','g')) and m.created_at>=review.created_at),'{}');
    end if;
  end loop;
  foreach merchant in array merchant_ids loop
    if exists(select 1 from public.transactions where merchant_id=merchant) or exists(select 1 from public.organization_rules where merchant_id=merchant) then
      update public.merchants set created_by='ai' where id=merchant;
      continue;
    end if;
    begin
      delete from public.merchants where id=merchant;
      merchants_deleted := merchants_deleted+(case when found then 1 else 0 end);
    exception when foreign_key_violation then
      update public.merchants set created_by='ai' where id=merchant;
    end;
  end loop;
  update public.agent_proposals set status='rejected',result=jsonb_build_object('reset',true),decided_at=coalesce(decided_at,now()) where id=any(proposals);
  return jsonb_build_object('proposals',cardinality(proposals),'restored',restored,'kept',kept,'rulesDeleted',rules_deleted,
    'rulesRestored',rules_restored,'rulesKept',rules_kept,'merchantsDeleted',merchants_deleted);
end;
$$;
revoke all on function public.reset_auto_organization() from public,anon,authenticated;
select public.reset_auto_organization();

1	import { randomUUID } from "node:crypto";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { z } from "zod";
4	import { calendarDate } from "@/lib/finance/calendar";
5	import { formatMoney } from "@/lib/finance/format";
6	import { loadWorkspaceSettings } from "@/lib/settings";
7	import { closingMovedTo } from "./account-closing";
8	import type { BankLeg } from "./transit";
9	
10	// Money moved between the owner's own accounts is a transfer, never income or spending.
11	// Detection is deterministic and IBAN-only: a row's counterparty IBAN is one of the owner's
12	// own accounts. Every decision goes through the audited link RPCs, so each one can be undone.
13	
14	export const MATCH_DAYS = 3;
15	// A closing row says which account the money went to, and it can be archived well after the bank's row arrived.
16	const CLOSING_MATCH_DAYS = 30;
17	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
18	
19	export function normalizeIban(value: string) {
20	  const iban = value.replace(/\s/g, "").toUpperCase();
21	  return IBAN.test(iban) ? iban : null;
22	}
23	
24	/** Every IBAN-shaped value in an original source row (counterparty columns differ per bank). */
25	export function sourceIbans(row: unknown) {
26	  if (!row || typeof row !== "object") return [];
27	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
28	}
29	
30	export type TransferCandidate = {
31	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
32	  reviewReasons: string[]; ibans: string[]; text?: string; counterparty?: string; transferId?: string | null;
33	  /** The account a closing row says this money went to. */
34	  closingTo?: string;
35	};
36	
37	// Without an IBAN, only the bank's own wording proves own money: a cash machine, or Scalable Capital
38	// once the owner connected Scalable (their withdrawals arrive without the broker's IBAN).
39	const CASH = /\b(bargeldauszahlung|bargeldeinzahlung|geldautomat|cash withdrawal|atm withdrawal|cash deposit)\b/i;
40	const SCALABLE = /\bscalable capital\b/i, SCALABLE_LABEL = /\bscalable\b/i;
41	export type NamedAccount = "cash" | "scalable";
42	export const NAMED_LABELS: Record<NamedAccount, string> = { cash: "Cash", scalable: "Scalable Capital" };
43	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string> }; // IBAN → account id / identifier id
44	
45	const days = (a: string, b: string) => Math.abs(Date.parse(a) - Date.parse(b)) / 86400000;
46	
47	/** Every posted leg in the workspace, so a lone leg can tell whether its other side exists. */
48	export type Leg = Pick<TransferCandidate, "id" | "accountId" | "postedOn" | "amountMinor" | "currencyCode">;
49	
50	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts, legs: Leg[] = rows, options: { scalable?: boolean } = {}) {
51	  // The posting account's own IBAN often appears in its row too; only the other side counts.
52	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
53	  const points = (row: TransferCandidate, accountId: string) => row.closingTo === accountId || counterparts(row).some(iban => own.tracked.get(iban) === accountId);
54	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
55	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= (out.closingTo || into.closingTo ? CLOSING_MATCH_DAYS : MATCH_DAYS);
56	  const used = new Set<string>();
57	  const pairs: { outId: string; inId: string }[] = [];
58	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
59	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
60	
61	  // IBAN-proven pairs first, closest date wins.
62	  for (const out of outs) {
63	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
64	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
65	    if (!used.has(out.id) && proven[0]) take(out, proven[0]);
66	  }
67	  // A leg whose other side is missing: the counterparty is an own account, and no opposite
68	  // leg exists in that account within the window. Untracked accounts are named by identifier;
69	  // tracked accounts by IBAN.
70	  const unpaired = (row: TransferCandidate, accountId: string) => !legs.some(other => other.id !== row.id && other.accountId === accountId
71	    && other.currencyCode === row.currencyCode && other.amountMinor === -row.amountMinor && days(row.postedOn, other.postedOn) <= MATCH_DAYS);
72	  const single = rows.flatMap((row): { transactionId: string; identifierId?: string; iban?: string }[] => {
73	    if (used.has(row.id)) return [];
74	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
75	    if (identifierId) return [{ transactionId: row.id, identifierId }];
76	    const iban = counterparts(row).find(item => own.tracked.has(item));
77	    const accountId = iban ? own.tracked.get(iban) : undefined;
78	    return iban && accountId && unpaired(row, accountId) ? [{ transactionId: row.id, iban }] : [];
79	  });
80	  const marked = new Set(single.map(item => item.transactionId));
81	  const named = rows.flatMap((row): { transactionId: string; account: NamedAccount }[] => {
82	    if (used.has(row.id) || marked.has(row.id) || counterparts(row).some(iban => own.tracked.has(iban) || own.untracked.has(iban))) return [];
83	    if (CASH.test(row.text ?? "")) return [{ transactionId: row.id, account: "cash" }];
84	    if (options.scalable && SCALABLE.test(`${row.counterparty ?? ""} ${row.text ?? ""}`)) return [{ transactionId: row.id, account: "scalable" }];
85	    return [];
86	  });
87	  return { pairs, single, named };
88	}
