91	 * Recent cash machine withdrawals with no other side yet. Until the owner accepts a card, one counts as money that left.
92	 * Older ones aren't asked about: that cash has most likely been spent, and the owner can set a Cash balance any time.
93	 */
94	export const CASH_CARD_DAYS = 30;
95	export function cashWithdrawals<T extends Pick<TransferCandidate, "id" | "postedOn" | "amountMinor" | "text" | "transferId">>(rows: T[], today: string, answered = new Set<string>()) {
96	  return rows.filter(row => row.amountMinor < 0n && !row.transferId && CASH.test(row.text ?? "") && !answered.has(row.id) && days(row.postedOn, today) <= CASH_CARD_DAYS);
