101	/**
102	 * Rows from a name the owner already sent money under to one of their own IBANs (their name on an old or
103	 * untracked account). A name alone is weak evidence, so these are only ever suggestions for the owner to accept.
104	 * `seen` are rows that already prove an own account (including linked transfers); `answered` already have a card.
105	 */
106	export function ownNameSuggestions(rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts, answered = new Set<string>()) {
107	  const names = new Map<string, string>();
108	  for (const row of seen) {
109	    const other = row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
110	    if (row.counterparty?.trim() && other.some(iban => own.tracked.has(iban) || own.untracked.has(iban))) names.set(nameKey(row.counterparty), row.counterparty.trim());
111	  }
112	  // A bank can put the holder's own name on a payment with no real other side (Revolut card refunds);
113	  // a transfer the owner made names them in the description too.
114	  return rows.flatMap(row => {
115	    const name = row.counterparty ? names.get(nameKey(row.counterparty)) : undefined;
116	    return name && !answered.has(row.id) && nameKey(row.text ?? "").includes(nameKey(name)) ? [{ transactionId: row.id, name }] : [];
117	  });
118	}
