151	async function loadRows(db: SupabaseClient, workspaceId: string, kind: "ordinary" | "transfer") {
152	  const rows: TransferCandidate[] = [];
153	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
154	    let query = db.from("transactions")
155	      .select("id, version, account_id, posted_on, amount_minor::text, currency_code, review_reasons, description, transfer_id, transaction_sources(source_transactions(original_row))")
156	      .eq("workspace_id", workspaceId).eq("status", "posted").eq("kind", kind);
157	    if (kind === "ordinary") query = query.is("transfer_id", null).is("refund_of_id", null);
158	    const { data, error } = await query.order("posted_on", { ascending: false }).order("id").range(from, from + PAGE - 1);
159	    if (error) throw new Error(error.message);
160	    for (const row of (data ?? []) as unknown as Row[]) {
161	      const reviewReasons = row.review_reasons ?? [];
162	      if (kind === "ordinary" && reviewReasons.some(reason => reason !== "source_transfer")) continue;
163	      const originals = (row.transaction_sources ?? []).map(source => source.source_transactions?.original_row);
164	      rows.push({ id: row.id, version: row.version, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor),
165	        currencyCode: row.currency_code, reviewReasons, ibans: [...new Set(originals.flatMap(sourceIbans))], text: row.description, counterparty: originals.map(counterpartyOf).find(Boolean), transferId: row.transfer_id });
166	    }
167	    if ((data ?? []).length < PAGE) break;
168	  }
169	  return rows;
170	}
