201	/** Raises one "your own money?" card per row, once: a declined card is never raised again. */
202	async function proposeOwnNames(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts) {
203	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "own_transfer").limit(5000);
204	  if (known.error) throw new Error(known.error.message);
205	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^own_transfer:/, "")));
206	  const found = ownNameSuggestions(rows, seen, own, answered);
207	  if (!found.length) return 0;
208	  const { locale } = await loadWorkspaceSettings(db, workspaceId);
209	  const byId = new Map(rows.map(row => [row.id, row]));
210	  const cards = found.map(({ transactionId, name }) => {
211	    const row = byId.get(transactionId)!, money = formatMoney(row.amountMinor < 0n ? -row.amountMinor : row.amountMinor, row.currencyCode, locale);
212	    return { workspace_id: workspaceId, agent: "chat", kind: "own_transfer", conflict_key: `own_transfer:${transactionId}`, confidence: 70,
213	      title: (row.amountMinor < 0n ? `${money} to ${name}: your own account?` : `${money} from ${name}: your own account?`).slice(0, 200),
214	      detail: `You sent money under the name ${name} to one of your own accounts before. If this is yours too, it moves to transfers and stops counting as ${row.amountMinor < 0n ? "spending" : "income"}.`,
215	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
216	      payload: ownTransferPayloadSchema.parse({ transactionId, name }) };
217	  });
218	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
219	  // A concurrent sync raised the same card first.
220	  if (error && error.code !== "23505") throw new Error(error.message);
221	  return data?.length ?? 0;
222	}
