246	export async function linkOwnTransfers(db: SupabaseClient, workspaceId: string) {
247	  const [own, rows, legs, transfers, scalable] = await Promise.all([loadOwnAccounts(db, workspaceId), loadTransferCandidates(db, workspaceId), loadLegs(db, workspaceId),
