282	// Generic context from one Enable Banking transaction, for any bank: no bank-specific code. Banks differ in what they send
283	// (ISO 20022 codes, proprietary codes, merchant category codes, remittance conventions), so every field is optional and
284	// "unknown" never blocks anything. None of this feeds ledger amounts; it only describes the row for the organizer.
285	
286	export const PAYMENT_TYPES = ["card", "transfer", "direct_debit", "cash", "fee_interest", "top_up", "exchange", "unknown"] as const;
287	export type PaymentType = (typeof PAYMENT_TYPES)[number];
288	
289	export type NormalizedBankTransaction = {
290	  payment_type: PaymentType;
291	  bank_code: string | null;
292	  bank_sub_code: string | null;
293	  mcc: string | null;
294	  counterparty_name: string | null;
295	  counterparty_iban: string | null;
296	  counterparty_bic: string | null;
297	  /** Additional identifications of the counterparty's account, as the bank sent them. */
298	  counterparty_ids: Identification[];
299	  /** The same for the owner's own side (card ids on card payments, for one neobank). */
300	  own_side_ids: Identification[];
301	  creditor_id: string | null;
302	  mandate_ref: string | null;
303	  instructed_amount: string | null;
304	  instructed_currency: string | null;
305	  exchange_rate: string | null;
306	  own_account: boolean;
307	};
308	type Identification = { identification: string; scheme_name?: string };
