310	// ISO 20022 external bank transaction codes (ExternalBankTransactionDomain1Code / Family1Code / Subfamily1Code,
311	// https://www.iso20022.org/external_code_list.page). Only the families and sub-families that decide the payment type.
312	// The most specific level wins: PMNT/CCRD/CWDL is a cash withdrawal although CCRD is a card family.
313	const ISO_SUBFAMILY: Record<string, PaymentType> = {
314	  CWDL: "cash", CDPT: "cash", // cash withdrawal / cash deposit
315	  POSD: "card", POSC: "card", // point-of-sale debit / credit card payment
316	  STDO: "transfer", ESCT: "transfer", DMCT: "transfer", XBCT: "transfer", BOOK: "transfer", // standing order, SEPA, domestic, cross-border, book transfer
317	  PMDD: "direct_debit", ESDD: "direct_debit", UPDD: "direct_debit", // direct debit payment, SEPA, unpaid
318	  INTR: "fee_interest", CHRG: "fee_interest", FEES: "fee_interest", COMM: "fee_interest", // interest, charges, fees, commission
319	};
320	const ISO_FAMILY: Record<string, PaymentType> = {
321	  CCRD: "card", MCRD: "card", // customer card / merchant card transactions
322	  ICDT: "transfer", RCDT: "transfer", ICCT: "transfer", RCCT: "transfer", // issued / received (cross-border) credit transfers
323	  IDDT: "direct_debit", RDDT: "direct_debit", // issued / received direct debits
324	  CNTR: "cash", // counter transactions
325	  MCOP: "fee_interest", // miscellaneous credit operations
326	};
327	const ISO_DOMAIN: Record<string, PaymentType> = { FORX: "exchange" };
328	
329	// Proprietary codes are matched as whole words of the upper-cased code, in this order (CARD_FEE is a fee, not a card payment).
330	// Words are tokens split on anything that isn't a letter or digit, so CARD_PAYMENT is CARD + PAYMENT.
331	const HEURISTICS: [PaymentType, RegExp][] = [
332	  ["exchange", /(?:^|_)(?:EXCHANGE|FX|FOREX)(?:_|$)/],
333	  ["top_up", /(?:^|_)(?:TOPUP|TOP_UP)(?:_|$)/],
334	  ["fee_interest", /(?:^|_)(?:FEE|FEES|CHARGE|CHARGES|INTEREST)(?:_|$)/],
335	  ["direct_debit", /(?:^|_)(?:DIRECT_DEBIT|DD|LASTSCHRIFT)(?:_|$)/],
336	  ["cash", /(?:^|_)(?:ATM|CASH|CWDL)(?:_|$)/],
337	  ["transfer", /(?:^|_)(?:TRANSFER|TRF)(?:_|$)/],
338	  ["card", /(?:^|_)CARD(?:_|$)/],
339	];
340	
341	const words = (value: string) => value.toUpperCase().replace(/[^A-Z0-9]+/g, "_").replace(/^_|_$/g, "");
342	
343	/** Payment type from the bank's transaction code: ISO 20022 tables first, then generic word matching, else "unknown". */
344	export function paymentType(code: string | null, subCode: string | null, description: string | null = null): PaymentType {
345	  const iso = [code, subCode].flatMap(value => (value ?? "").toUpperCase().split(/[^A-Z0-9]+/)).filter(token => /^[A-Z]{4}$/.test(token));
346	  for (const table of [ISO_SUBFAMILY, ISO_FAMILY, ISO_DOMAIN]) {
347	    for (const token of iso) if (table[token]) return table[token];
348	  }
349	  const text = words([code, subCode, description].filter(Boolean).join(" "));
350	  return HEURISTICS.find(([, pattern]) => pattern.test(text))?.[0] ?? "unknown";
351	}
