353	const SEPA_ID = "[A-Z]{2}\\d{2}[A-Z0-9]{3}[A-Z0-9]{1,28}";
354	// "Gläubiger-ID: DE98ZZZ09999999999", "CI DE98ZZZ...", "Creditor ID DE98ZZZ...", SEPA tag "CRED+DE98ZZZ...".
355	const CREDITOR_LABELLED = new RegExp(`(?:gl(?:ä|ae|a)ubiger[-\\s]?(?:id|identifikation(?:snummer)?)|creditor[-\\s]?id(?:entifier)?|\\bCI|\\bCRED)\\s*[:=+]?\\s*(${SEPA_ID})(?![A-Z0-9])`, "i");
356	// Any SEPA creditor identifier is recognisable by its ZZZ business code.
357	const CREDITOR_BARE = /\b([A-Z]{2}\d{2}ZZZ[A-Z0-9]{1,28})(?![A-Z0-9])/;
358	// "Mandatsref: M12345", "Mandatsreferenz M12345", "MREF+M12345", "Mandate reference M12345". A reference carries a digit.
359	const MANDATE = /(?:mandats?[-\s]?(?:ref(?:erenz)?)?|mref|mandate(?:\s+(?:ref(?:erence)?|id))?)\s*[:=+.]?\s*(?=[A-Za-z0-9\-_./?:()]*\d)([A-Za-z0-9\-_./?:()]{3,35})/i;
