398	  const rate = isRecord(record.exchange_rate) ? record.exchange_rate : {};
399	  const instructed = isRecord(rate.instructed_amount) ? rate.instructed_amount : isRecord(record.instructed_amount) ? record.instructed_amount : {};
400	  const instructedAmount = decimal(instructed.amount), instructedCurrency = clean(instructed.currency, 3);
401	  const hasInstructed = !!instructedAmount && !!instructedCurrency && /^[A-Z]{3}$/.test(instructedCurrency);
402	  const remittance = (tx.remittance_information ?? []).join(" ");
403	  const counterpartyIban = normalizedIban(isRecord(account) ? account.iban : null);
404	  return {
405	    payment_type: paymentType(bankCode, subCode, clean(code.description, 200)),
406	    bank_code: bankCode, bank_sub_code: subCode,
407	    mcc: clean(record.merchant_category_code, 10),
408	    counterparty_name: clean(isRecord(party) ? party.name : null, 500),
409	    counterparty_iban: counterpartyIban,
410	    counterparty_bic: clean(isRecord(agent) ? agent.bic_fi ?? agent.bic : null, 11),
411	    counterparty_ids: identifications(record[`${side}_account_additional_identification`]),
412	    own_side_ids: identifications(record[`${own}_account_additional_identification`]),
413	    ...sepaReferences(remittance),
414	    instructed_amount: hasInstructed ? instructedAmount : null, instructed_currency: hasInstructed ? instructedCurrency : null,
