446	// Normalized bank context for ledger transactions: transaction -> source row (import_id, row_number) -> bank_transaction_raw.
447	// Transactions that did not come from a bank sync, or whose import was undone, simply have no entry. The raw JSON stays
448	// in the table; the organizer reads the normalized columns.
449	export type RawContext = NormalizedBankTransaction & { bank_id: string | null };
450	
451	const COLUMNS = ["bank_id", "payment_type", "bank_code", "bank_sub_code", "mcc", "counterparty_name", "counterparty_iban", "counterparty_bic",
452	  "counterparty_ids", "own_side_ids", "creditor_id", "mandate_ref", "instructed_amount", "instructed_currency", "exchange_rate", "own_account"];
453	const CHUNK = 200;
454	const chunks = <T,>(items: T[]) => Array.from({ length: Math.ceil(items.length / CHUNK) }, (_, index) => items.slice(index * CHUNK, (index + 1) * CHUNK));
