456	export async function loadRawContext(db: SupabaseClient, workspaceId: string, transactionIds: string[]): Promise<Map<string, RawContext>> {
457	  const wanted = new Map<string, { import_id: string; row_number: number }[]>();
458	  for (const ids of chunks([...new Set(transactionIds)])) {
459	    const links = await db.from("transaction_sources").select("transaction_id, source_transactions!inner(import_id, row_number, workspace_id)")
460	      .in("transaction_id", ids).eq("source_transactions.workspace_id", workspaceId);
461	    if (links.error) throw new Error(links.error.message);
462	    for (const link of links.data as unknown as { transaction_id: string; source_transactions: { import_id: string; row_number: number } | { import_id: string; row_number: number }[] }[]) {
463	      const sources = Array.isArray(link.source_transactions) ? link.source_transactions : [link.source_transactions];
464	      wanted.set(link.transaction_id, [...wanted.get(link.transaction_id) ?? [], ...sources.map(({ import_id, row_number }) => ({ import_id, row_number }))]);
465	    }
466	  }
467	  const byImport = new Map<string, Set<number>>();
468	  for (const sources of wanted.values()) for (const { import_id, row_number } of sources) byImport.set(import_id, (byImport.get(import_id) ?? new Set()).add(row_number));
469	  const found = new Map<string, RawContext>();
470	  for (const [importId, rows] of byImport) {
471	    for (const numbers of chunks([...rows])) {
472	      const loaded = await db.from("bank_transaction_raw").select(`row_number, ${COLUMNS.join(", ")}`).eq("workspace_id", workspaceId).eq("import_id", importId).in("row_number", numbers);
473	      if (loaded.error) throw new Error(loaded.error.message);
474	      for (const row of loaded.data as unknown as (RawContext & { row_number: number })[]) found.set(`${importId}:${row.row_number}`, row);
475	    }
476	  }
477	  const context = new Map<string, RawContext>();
478	  for (const [transactionId, sources] of wanted) {
479	    const hit = sources.map(source => found.get(`${source.import_id}:${source.row_number}`)).find(Boolean);
480	    if (hit) context.set(transactionId, hit);
481	  }
482	  return context;
483	}
