create function public.guard_split_transaction() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if exists(select 1 from public.transaction_split_sets where transaction_id=old.id and undone_at is null) and
    (new.amount_minor,new.currency_code,new.account_id,new.posted_on,new.posted_at,new.status,new.kind,new.category_id,new.transfer_id,new.refund_of_id,new.review_reasons)
    is distinct from (old.amount_minor,old.currency_code,old.account_id,old.posted_on,old.posted_at,old.status,old.kind,old.category_id,old.transfer_id,old.refund_of_id,old.review_reasons)
    then raise exception 'Undo splits before changing source classification, category or links' using errcode='22023'; end if;
  -- Inbound refund links also need a deliberate category allocation, never the hidden parent category.
  if new.refund_of_id is not null and exists(select 1 from public.transaction_split_sets where transaction_id=new.refund_of_id and undone_at is null)
    then raise exception 'Undo original transaction splits before linking a refund' using errcode='22023'; end if;
  return new;
end;
$$;
create trigger transactions_split_guard before insert or update on public.transactions for each row execute function public.guard_split_transaction();

create function public.split_transaction(p_transaction_id uuid,p_expected_version integer,p_children jsonb,p_request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare parent public.transactions%rowtype; prior public.transaction_split_sets%rowtype; child jsonb; total numeric:=0; split_id uuid:=gen_random_uuid(); normalized jsonb:='[]'; child_amount bigint; child_category uuid; position integer:=0;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if p_request_id is null or p_children is null or jsonb_typeof(p_children)<>'array' or jsonb_array_length(p_children) not between 2 and 20 then raise exception 'Two to twenty exact allocations required' using errcode='22023'; end if;
  select * into parent from public.transactions where id=p_transaction_id and public.owns_workspace(workspace_id) for update;
  if not found then raise exception 'Transaction not found' using errcode='P0002'; end if;
  for child in select value from jsonb_array_elements(p_children) loop
    if jsonb_typeof(child)<>'object' or child-array['amount_minor','category_id','note']<>'{}'::jsonb or jsonb_typeof(child->'amount_minor') is distinct from 'string'
      or child->>'amount_minor' !~ '^-?[0-9]{1,19}$' or jsonb_typeof(child->'note') is distinct from 'string' or char_length(child->>'note')>500
      or not(child ? 'category_id') or jsonb_typeof(child->'category_id') not in ('string','null') then raise exception 'Invalid allocation' using errcode='22023'; end if;
    begin child_amount:=(child->>'amount_minor')::bigint; child_category:=(child->>'category_id')::uuid;
    exception when numeric_value_out_of_range or invalid_text_representation then raise exception 'Invalid allocation money or category' using errcode='22023'; end;
    if child_amount=0 or sign(child_amount)<>sign(parent.amount_minor) then raise exception 'Allocations must have the source amount direction' using errcode='22023'; end if;
    if child_category is not null and not exists(select 1 from public.categories where id=child_category and workspace_id=parent.workspace_id) then raise exception 'Category not found' using errcode='P0002'; end if;
== guard_verified_transaction_link supabase/migrations/202610010041_verified_transaction_links.sql
create function public.guard_verified_transaction_link() returns trigger language plpgsql security definer set search_path='' as $$
declare original public.transactions%rowtype; refunded numeric;
begin
  if current_setting('moneo.link_edit',true) is distinct from 'on' and exists(select 1 from public.transactions where refund_of_id=old.id)
    and (new.kind,new.status,new.amount_minor,new.account_id,new.currency_code,new.posted_on,new.posted_at,new.transfer_id,new.refund_of_id,new.review_reasons)
      is distinct from (old.kind,old.status,old.amount_minor,old.account_id,old.currency_code,old.posted_on,old.posted_at,old.transfer_id,old.refund_of_id,old.review_reasons)
    then raise exception 'Undo linked refunds before changing original financial evidence' using errcode='22023'; end if;
  if current_setting('moneo.link_edit',true) is distinct from 'on' and new.refund_of_id is not null and new.refund_of_id is distinct from old.refund_of_id then
    select * into original from public.transactions where id=new.refund_of_id and workspace_id=new.workspace_id for update;
    if not found or original.currency_code<>new.currency_code then raise exception 'Use the verified refund action with dated FX evidence' using errcode='22023'; end if;
    select coalesce(sum(case when l.id is not null then l.original_equivalent_minor::numeric else t.amount_minor::numeric end),0) into refunded
      from public.transactions t left join public.transaction_links l on l.primary_transaction_id=t.id and l.operation='refund' and l.undone_at is null where t.refund_of_id=original.id and t.id<>new.id;
    if refunded+new.amount_minor>abs(original.amount_minor::numeric) then raise exception 'Combined refunds exceed the original expense' using errcode='22023'; end if;
  end if;
  if current_setting('moneo.link_edit',true) is distinct from 'on' and exists(select 1 from public.transaction_links l where l.undone_at is null and (l.primary_transaction_id=old.id or (l.operation='transfer' and l.counterpart_transaction_id=old.id)))
    and (new.kind,new.status,new.amount_minor,new.account_id,new.currency_code,new.posted_on,new.posted_at,new.transfer_id,new.refund_of_id,new.review_reasons)
      is distinct from (old.kind,old.status,old.amount_minor,old.account_id,old.currency_code,old.posted_on,old.posted_at,old.transfer_id,old.refund_of_id,old.review_reasons)
    then raise exception 'Undo the verified link before changing its financial classification' using errcode='22023'; end if;
  return new;
end;
$$;
create trigger transactions_verified_link_guard before update on public.transactions for each row execute function public.guard_verified_transaction_link();

create function public.link_transactions(p_operation text,p_primary_id uuid,p_expected_version integer,p_other_id uuid,p_other_version integer,p_fx_rate_id uuid,p_fees jsonb,p_request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.transactions%rowtype; b public.transactions%rowtype; rate public.fx_rates%rowtype; prior public.transaction_links%rowtype; fee jsonb; normalized jsonb:='[]'; fee_id uuid; fee_amount bigint; fee_category uuid; principal_a numeric; principal_b numeric; equivalent numeric; refunded numeric; evidence jsonb; input jsonb; before_rows jsonb; after_rows jsonb; link uuid:=gen_random_uuid(); changes public.transactions%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if p_operation is null or p_operation not in ('transfer','refund') or p_primary_id is null or p_other_id is null or p_primary_id=p_other_id or p_request_id is null
